import heapq, sys


def ps(l):
    n = len(l)
    nxt = 1
    heap = []
    ans = []
    for i in range(n):
        heapq.heappush(heap, l[i])
        while heap and heap[0] == nxt:
            nxt += 1
            heapq.heappop(heap)
        if not heap:
            ans.append(i)
    return ans


