class Union:
    def __init__(self, n):
        self.p    = [i for i in range(n+1)]
        self.rank = [0] * (n+1) 

    def find(self, x):
        if self.p[x] != x:
            self.p[x] = self.find(self.p[x])
        return self.p[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x != y:
            if self.rank[x] < self.rank[y]:
                self.p[x]     = y
                self.rank[y] += self.rank[x]
            else:
                self.p[y]     = x
                self.rank[x] += self.rank[y]

def push(g, u, v):
    if u not in g:
        g[u] = []
    if v not in g:
        g[v] = []

    g[u].append(v)
    g[v].append(u)


def push_c(cnt, u, i):
    if u not in cnt:
        cnt[u] = set()
    cnt[u].add(i) 

def process(cnt, tup, deg0, order, g, U, u):
    if len(cnt[u]) > 0:
        i = next(iter(cnt[u]))
    else:
        return

    for v in tup[i]:
        cnt[v].remove(i)

        if len(cnt[v]) == 1:
            deg0.append(v)

    v, w = None, None
    for x in tup[i]:
        if x == u:
            continue
        if v is None:
            v = x
        else:
            w = x

    order.append(i)

    if U.find(u) != U.find(v):
        U.union(u, v)
        push(g, u, v)

    if U.find(u) != U.find(w):
        U.union(u, w)
        push(g, u, w)

