class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        dp = [-1 for _ in s]
        n = len(s)

        def recurse(i: int) -> int:
            if i == n:
                return 1

            if dp[i] != -1:
                return dp[i]

            result = 0
            val = 0
            for j in range(i, n):
                val = 10 * val + (ord(s[j]) - ord('0'))
                if val > k:
                    break
                elif j == n - 1 or s[j + 1] != '0':
                    result = (result + recurse(j + 1)) % MOD
            dp[i] = result
            return result

        return recurse(0)



class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        n = len(s)
        b = ord('0')
        MOD = 10 ** 9 + 7
        dp = collections.deque([0] * 10)
        dp[0] = 1
        for i in range(n - 1, -1, -1):
            if s[i] == '0':
                dp.pop()
                dp.appendleft(0)
                continue
            num = 0
            cnt = 0
            for j in range(i, n):
                num = num * 10 + ord(s[j]) - b
                if num <= k:
                    cnt += dp[j - i] % MOD
                else:
                    break
            dp.appendleft(cnt % MOD)
            dp.pop()
        return dp[0]

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        dp = [0] * (days[-1] + 1)
        pos = 0

        for i in range(1, days[-1] + 1):
            if i == days[pos]:
                d1 = i - 1
                d2 = i - 7 if i - 7 > 0 else 0
                d3 = i - 30 if i - 30 > 0 else 0
                dp[i] = min(dp[d1] + costs[0], dp[d2] + costs[1], dp[d3] + costs[2])
                pos += 1
            else:
                dp[i] = dp[i - 1]

        return dp[-1]

