class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        if n <= 1: return n
        b = int(math.log2(n)) + 1        
        return ((1 << b)-1) - self.minimumOneBitOperations(n - (1 << (b-1)))

class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        result = 0
        while n:
            result = ((n & -n) << 1) - 1 - result
            n -= n & -n
        return result

class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        s = 0
        m = n
        while m:
            s += m & 1
            m >>= 1

        k = 1
        while s:
            s -= bool(n & k)
            n ^= (s & 1) and k
            k <<= 1

        return n

