         if self.isprime(divs):
                 return divs + steps

         primes = self.primes(divs)
         # if a factor is three, you have to copy n, then paste it twice. 1 + 2 = 3, 1 + n - 1 = n
         # therefore, the number of steps is the sum of the primes

         return steps + sum(primes)
