class Solution:
    def maxJumps(self, A: List[int], d: int) -> int:
        n = len(A)
        dp = [1] * n
        for a, i in sorted([a, i] for i, a in enumerate(A)):
            j = i - 1
            while j >= 0 and A[j] < A[i] and i - j <= d:
                dp[i] = max(dp[i], dp[j] + 1)
                j -= 1
            j = i + 1
            while j < n and A[j] < A[i] and j - i <= d:
                dp[i] = max(dp[i], dp[j] + 1)
                j += 1
        return max(dp)

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        res = 0
        visited = {}

        def dfs(i):
            if i in visited:
                return visited[i]

            step = 1

            i_right = i + 1
            while i_right < len(arr) and i_right - i <= d:
                if arr[i_right] >= arr[i]:
                    break
                step = max(step, 1+dfs(i_right))
                i_right += 1

            i_left = i - 1
            while i_left >= 0 and i - i_left <= d:
                if arr[i_left] >= arr[i]:
                    break
                step = max(step, 1+dfs(i_left))
                i_left -= 1
            visited[i] = step
            return step


        for i in range(len(arr)):
            res = max(res, dfs(i))

        return res

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        dp = [1] * (len(arr) + 1)
        stack = []
        for i, n in enumerate(arr + [1000000]):
            while stack and arr[stack[-1]] < n:
                same_height_idx = [stack.pop()]
                while stack and arr[stack[-1]] == arr[same_height_idx[0]]:
                    same_height_idx.append(stack.pop())
                for j in same_height_idx:
                    # jump to left
                    if i - j <= d:
                        dp[i] = max(dp[i], dp[j] + 1)
                    # jump to right
                    if stack and j - stack[-1] <= d:
                        dp[stack[-1]] = max(dp[stack[-1]], dp[j] + 1)
            stack.append(i)
        return max(dp[:-1])

class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:

        #https://leetcode.com/problems/shortest-common-supersequence/discuss/639784/Python-DP-with-detailed-explanation
        #https://leetcode.com/problems/shortest-common-supersequence/discuss/674175/Python-Very-simple-solution-with-DP-Table-Memory-95

        m,n = len(str1)+1, len(str2)+1
        dp = ['']*n
        for c in range(n):
