class Solution:
    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
        stack = deque()

        for i in range(len(nums)):
            nums[i] += stack[0] if stack else 0
            while stack and stack[-1] < nums[i]:
                stack.pop()
            if i >= k and stack and stack[0] == nums[i-k]:
