class Solution:
    def superEggDrop(self, K: int, N: int) -> int:
        if N == 0 or N == 1:
            return N

        if K == 1:
            return N

        if t[K][N] != -1:
            return t[K][N]

        mn, l, h = sys.maxsize, 1, N
        while l <= h:
            mid = (l + h) // 2

            down_temp = self.superEggDrop(K - 1, mid - 1)
            up_temp = self.superEggDrop(K, N - mid)

            res = 1 + max(down_temp, up_temp)

            if down_temp < up_temp:
                l = mid + 1
            else:
                h = mid - 1

            mn = min(mn, res)

        t[K][N] = mn

        return mn

class Solution:
    def superEggDrop(self, K: int, N: int) -> int:
        # special case for K = 1
        if K == 1:
            return N

        # initialize data
        Rp = [i for i in range(0, N+1)]
        R = [0] * (N+1)
        R[1] = 1

        k = 2
        while k <= K:
            l1 = 0
            for n in range(2, N+1):
                #if n < 2**k:
                #    R[n] = n.bit_length() 
                if Rp[n-l1-1] >= R[n-1]:
                    R[n] = R[n-1] + 1
                else:
                    R[n] = R[n-1]

                if R[n] > R[n-1]:
                    l1 = n-1

            Rp, R = R, Rp
            k += 1

        return Rp[N]

class Solution:
    def superEggDrop(self, K: int, N: int) -> int:
        cache = {}
        return self.drop_iter(K, N, cache)

    def drop_iter(self, K, N, cache):
        if K == 1:
            return N
        if N == 0:
            return 0
        if (K, N) in cache:
            return cache[(K, N)]
        res = float('inf')
        # for i in range(1, N+1):
        #     temp = max(self.drop_iter(K, N-i, cache), self.drop_iter(K-1, i-1, cache)) + 1
        #     res = min(res, temp)
        left = 1
        right = N
        # self.drop_iter(K, N-i, cache) 单调减
        # self.drop_iter(K-1, i-1, cache) 单调增
        while left <= right:
            mid = (left + right) // 2
            borke = self.drop_iter(K - 1, mid - 1, cache)
            not_broke = self.drop_iter(K, N - mid, cache)
            if borke > not_broke:
                right = mid - 1
                res = min(borke + 1, res)
            else:
                left = mid + 1
                res = min(not_broke + 1, res)

        cache[(K, N)] = res
        return res

