class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        if startFuel >= target: return 0
        heap = [] #record the reachable gas for now
        stop = 0 #total stops
        dist = startFuel #reachable distance
        for d, g in stations:
            if dist >= target: #if reach target, return
                return stop
            while heap and dist < d: #make sure we can reach current station by make minimum stops
                gas = heapq.heappop(heap)
                dist += -gas
                stop += 1
            if dist < d: #if not reachable, return -1
                return -1
            heapq.heappush(heap, (-g)) #add current gas to heap for future stop
        if dist >= target:
                return stop
        while heap: #add the rest gas in heap from max to min to reach the target
            g = heapq.heappop(heap)
            stop += 1
            dist += -g
            if dist >= target:
                return stop
        return -1






class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        if target <= startFuel:
            return 0

        if not stations:
            return -1

        dp = [startFuel]
        stops = 0
        lastd = 0
        for d, fuel in stations:
            for i in range(stops, len(dp)):
                dp[i] -= d - lastd
                if dp[i] < 0:
                    stops = i + 1

            if stops == len(dp):
                return -1

            dp.append(dp[-1] + fuel)
            for i in range(len(dp) - 2, stops, -1):
                dp[i] = max(dp[i], dp[i - 1] + fuel)

            if dp[stops] >= target - d:
                return stops

            lastd = d

        while stops < len(dp):
            if dp[stops] >= target - lastd:
                return stops
            stops += 1

        return -1
class Solution:
