     def numberToWords(self, num):
         """
         :type num: int
         :rtype: str
         """
         num_lyst = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine']
         tens_lyst = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']
         under20_lyst = ['Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
         large_scale = ['', 'Thousand', 'Million', 'Billion']

         def convert(num):
             out_str = ''
             hundred = num // 100
             ten_digit = num % 100
             if hundred:
                 out_str += num_lyst[hundred] + ' ' + 'Hundred '
             if ten_digit:
                 if ten_digit < 10:
                     out_str += num_lyst[ten_digit]
                 elif ten_digit < 20:
                     out_str += under20_lyst[ten_digit % 10]
                 else:
                     out_str += tens_lyst[ten_digit // 10] + ' ' + num_lyst[ten_digit % 10]

             return out_str.strip()

         if not num:
             return 'Zero'


         res = num // 1000    # 商
         last3 = num % 1000     # 余数，后三位
         ans = ''

         while res or last3:
             if last3:
                 ans = convert(last3) + ' ' + large_scale.pop(0) + ' '+ ans
             else:
                 large_scale.pop(0)

             last3 = res % 1000
             res = res //1000

         return ans.strip()






class Solution:
     def parseHundred(self, n):
         to19 = 'One Two Three Four Five Six Seven Eight Nine Ten Eleven Twelve Thirteen Fourteen Fifteen Sixteen Seventeen Eighteen Nineteen'.split()
         tens = 'Twenty Thirty Forty Fifty Sixty Seventy Eighty Ninety'.split()

         if n == 0:
             return ''

         w = ""

         while n > 0:
             if n > 99:
                 digit = n//100

                 w += to19[digit-1] + ' ' + 'Hundred'
                 n = n % 100

                 if n != 0:
                     w += ' '

             else:
                 if n <= 19:
                     w +=  to19[n-1]
                     n = 0
                 else:
                     digit = n// 10
                     w += tens[digit-2] 
                     n = n % 10

                     if n != 0:
                         w += ' '

         return w


     def numberToWords(self, num):
         """
         :type num: int
         :rtype: str
         """
         thousands = ['', ' Thousand ', ' Million ', ' Billion ']
         i = 0
         w = ""

         if num == 0:
             return 'Zero'

         while num > 0:
             digits = num % 1000
             if digits != 0:
                 w = self.parseHundred(digits) +  thousands[i] + w
             num = num//1000

             i += 1

         return w.strip()

