class Solution:
    def isValid(self, s: str) -> bool:
        stack = list()

        for ch in s:
            if ch == 'a':
                stack.append('a')
            elif ch == 'b':
                if stack and stack[-1] == 'a':
                    stack[-1] = 'b'
                else:
                    return False
            elif ch == 'c':
                if stack and stack[-1] == 'b':
                    stack.pop()
                else:
                    return False
            else:
                return False

        return (len(stack) == 0)

