class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        for answer in range(len(s), 0, -1):
            num_splits = answer - 1
            for split_points in combinations(range(1, len(s)), num_splits):
                current = 0
                words = set()
                for split_point in split_points:
                    words.add(s[current:split_point])
                    current = split_point
                words.add(s[current:])
                if len(words) == answer:
                    return answer

class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        self.x, n = 0, len(s)
        def maxUniqueSplit_(i=0, S=set()):
            if s[i:] not in S:
                self.x = max(self.x, len(S) + 1)

            for j in range(i + 1, n):
                if s[i : j] not in S and len(S) + 1 + n - j > self.x:
                    maxUniqueSplit_(j, S.union({s[i : j]}))


        maxUniqueSplit_()
        return self.x

class Solution:
    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        A.sort()
        dp = {}
        mod = 10**9+7
        for a in A:
            dp[a] = 1
            for b in A:
                if a%b==0 and b in dp and a//b in dp:
                    dp[a] += dp[b]*dp[a//b]
                    dp[a] %= mod

        return sum(dp.values())%mod
class Solution:
    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        mod = 10 ** 9 + 7
        A.sort()
        parents = dict()
        seen = set()
        for a in A:
            tot = 1
            for s in seen:
                if a % s == 0:
                    b = a // s
                    if b in seen:
                        tot += parents[s] * parents[b]
            parents[a] = tot
            seen.add(a)
        return sum(parents.values()) % mod



class Solution:
    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        A.sort()
        dp = {}
        res = 0
        for i in range(len(A)):
            dp[A[i]] = 1
            for j in range(i):
                if A[j] * A[j] == A[i]:
                    dp[A[i]] += dp[A[j]] * dp[A[j]]
                    dp[A[i]] %= 1000_000_007
                elif A[j] * A[j] > A[i]:
                    div = A[i] // A[j]
                    if div * A[j] == A[i] and div in dp:
                        dp[A[i]] += dp[A[j]] * dp[div] * 2
                        dp[A[i]] %= 1000_000_007
            res += dp[A[i]]
            res %= 1000_000_007
        return res
class Solution:
    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        n = len(A)
        A.sort()
        dp = [1] * n
        res = 0
        for i in range(n):
            s = 0
            e = i - 1
            for s in range(i):
                while s <= e and A[s] * A[e] > A[i]:
                    e -= 1

                if s > e:
                    break

                if A[s] * A[e] == A[i]:
                    dp[i] += ((dp[s] * dp[e] * 2) if s != e else (dp[s] * dp[e]))
                    dp[i] = dp[i] % (10 ** 9 + 7)
                    e -= 1

            res += dp[i]
            res = res % (10 ** 9 + 7)

        return res

class Solution:
    def numFactoredBinaryTrees(self, A: List[int]) -> int:
        A.sort()
        O = {}
        ans = 0
        for a in A:
            if a not in O:
                O[a] = 1
            for k, v in list(O.items()):
                if a % k == 0 and a // k in O:
                    O[a] += v * O[a // k]
            ans += O[a]
        return ans % 1000000007

