     def numDistinct(self, s, t):
         """
         :type s: str
         :type t: str
         :rtype: int
         """
         if len(s) < len(t):
             return 0
         dp = [0] * len(s)
         for i in range(len(s)):
             dp[i] = dp[i-1] if i > 0 else 0
             if s[i] == t[0]:
                 dp[i] += 1

