class Solution:

    def dfs(self, pos):
        if pos==self.n:
            self.ans += 1
            return

        last = None
        for i, val in enumerate(self.a):
            if self.usable[i]:
                if val == last:
                    continue
                if pos-1 >= 0 and (val + self.rec[pos-1]) not in self.square:
                    continue

                self.usable[i] = False
                self.rec[pos] = val
                self.dfs(pos + 1)
