            for j in range(n):
                for loc in range(4):
                    k = seen[i][j][loc]
                    if k == 0:
                        #print(i,j,k, seen)
                        count += 1
                        dfs(i,j,loc)
        return count

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:

        N = len(grid)
        base = N * (N + 1)
        parent = [i for i in range(2 * base)]

        def find(x):
            if parent[x] != parent[parent[x]]:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            parent[find(x)] = find(y)
            return find(y)

        for i in range(N):
            for j in range(N):
                up, down, left, right = i * N + j, (i + 1) * N + j, base + i * (N + 1) + j, base + i * (N + 1) + j + 1

                if grid[i][j] == '/':
                    union(up, left)
                    union(down, right)
                elif grid[i][j] == '\\\\':
                    union(up, right)
                    union(down, left)
                else:
                    union(up, left)
                    union(down, right)
                    union(left, right)

        comp = set()
        for i in range(2 * base):
            comp.add(find(i))

        return len(comp)

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        N = len(grid)     
        D = list(range(N*N*4))
        res = [len(D)]
        def find(D,i):
            if D[i]==i:
                return i
            return find(D,D[i])

        def union(D,i,j):
            pi = find(D,i)
            pj = find(D,j)
            if pi==pj:
                return
            else:
                D[pi] = pj
                res[0] -= 1

        def idx(i,j,e):
            return (i*N+j)*4+e



        for i in range(N):
            for j in range(N):
                if i>0:
                    union(D,idx(i-1,j,2),idx(i,j,0))
                if j>0:
                    union(D,idx(i,j-1,1,),idx(i,j,3))
                if grid[i][j]!='/':
                    union(D,idx(i,j,0),idx(i,j,1))
                    union(D,idx(i,j,2),idx(i,j,3))
                if grid[i][j]!='\\\\':
                    union(D,idx(i,j,0),idx(i,j,3))
                    union(D,idx(i,j,1),idx(i,j,2))
        return res[0]

class Solution:
     def numberOfArithmeticSlices(self, A):
         """
         :type A: List[int]
         :rtype: int
         """

         if len(A) < 3:
             return 0

         count = 0
         l = len(A)

         i = 0
         while i < l-2:
             j = i + 2
             while j < l:
                 if A[i]-A[i+1] == A[j-1]-A[j]:
                     count += j-i-1
                     j += 1
                 else:
                     i = j-1
                     break
             if j == l:
                 break

         return count

