class Solution:
    def minFlipsMonoIncr(self, S: str) -> int:
        dp = 0
        ones = 0

        for c in S:
            if c == '0':
                # 結尾為 1 的翻法的最小步驟數 = 1 + dp[i-1]
                # 結尾為 0 的翻法的最小步驟數 = 前面 1 的個數
                # 所以 dp[i] = min(1 + dp[i-1], # of 1s)
                dp = min(1 + dp, ones)
            else:
                # 結尾為 1 的翻法的最小步驟數 = dp[i-1]
                # 結尾為 0 的翻法的最小步驟數 = 1 + 前面 1 的個數
                # 所以 dp[i] = min(dp[i-1], 1 + # of 1s)
                dp = min(dp, 1 + ones)
                ones += 1

        return dp
class Solution:
    def minFlipsMonoIncr(self, S: str) -> int:

        n, prefix, total, res = len(S), 0, S.count('1'), sys.maxsize
        for i in range(n + 1):
            res = min(res, prefix + len(S) - i - total + prefix)
            if i < n: prefix += 1 if S[i] == '1' else 0
        return res

class Solution:
    def numSubarraysWithSum(self, A: List[int], S: int) -> int:
        n = len(A)

        i, j, total, res = 0, 0, 0, 0
        while j < n:
            total += A[j]
            while i < j and total > S:
                total -= A[i]
                i += 1
            if total == S:
                res += 1
                # There could be multiple 0 between i & j.
                k = i
                while k < j and A[k] == 0:
                    k += 1
                    res += 1
            j += 1
        return res
class Solution:
    def numSubarraysWithSum(self, A: List[int], S: int) -> int:
        size = len(A)
        l, r, total, cnt = [0] * 4
        if S == 0:
            l = 1
            for x in A:
                if x == 0:
                    cnt += l
                    l += 1
                else:
                    l = 1
            return cnt
        while r < size and total < S:
            total += A[r]
            r += 1
        if r == size and total < S:
            return 0
        while r < size:
            cnt1, cnt2 = 1, 1
            while l < r and A[l] == 0:
                l += 1
                cnt1 += 1
            while r < size and  A[r] == 0:
                r += 1
                cnt2 += 1
            cnt += cnt1 * cnt2
            l += 1
            r += 1
        if A[-1] == 1:
            cnt += 1
            while l < size and A[l] == 0:
                cnt += 1
                l += 1
        return cnt 
