class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        n = len(grid)
        m = len(grid[0])

        F = [i for i in range(m * n)]
        def find(x):
            if x == F[x]:
                return x
            else:
                F[x] = find(F[x])
                return F[x]

        for i in range(n):
            for j in range(m):
                if i > 0 and grid[i-1][j] == grid[i][j]:
                    f1 = find((i-1)*m+j)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
                if j > 0 and grid[i][j-1] == grid[i][j]:
                    f1 = find((i)*m+j-1)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
        return False
class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [[0,-1], [0,1], [-1,0], [1,0]]
        visited = [[False]*n for i in range(m)]

        def dfs(y, x, py, px, c):

            visited[y][x] = True
            for d in dirs:
                ny, nx = y+d[0], x+d[1]
                if ny < 0 or ny >= m or nx < 0 or nx >= n or (ny == py and nx == px) or grid[ny][nx] != c:
                    continue
                if visited[ny][nx] or dfs(ny, nx, y, x, c):
                    return True

            return False

        for i in range(m):
            for j in range(n):
                if not visited[i][j] and dfs(i, j, -1, -1, grid[i][j]):
                    return True

        return False
class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        R = len(grid)
        C = len(grid[0])
        N = R * C
        parents = [i for i in range(N)]

        def ufind(a):
            if parents[a] == a:
                return a
            parents[a] = ufind(parents[a])
            return parents[a]

        def uunion(a, b):
            aa = ufind(a)
            bb = ufind(b)
            if aa == bb:
                return False
            parents[bb] = aa
            return True

        def decode(row, col):
            return row * C + col

        for row in range(R):
            for col in range(C):
                if row + 1 < R and grid[row + 1][col] == grid[row][col]:
                    if not uunion(decode(row, col), decode(row + 1, col)):
                        return True
                if col + 1 < C and grid[row][col + 1] == grid[row][col]:
                    if not uunion(decode(row, col), decode(row, col + 1)):
                        return True

        return False
