class Solution:
     def countNumbersWithUniqueDigits(self, n):
         """
         :type n: int
         :rtype: int
         """
         if n ==0:
             return 1
         elif n == 1:
             return 10
         else:
             return (self.countNumbersWithUniqueDigits(n-1) - self.countNumbersWithUniqueDigits(n-2))*(11-n) + self.countNumbersWithUniqueDigits(n-1)

class Solution:
     def countNumbersWithUniqueDigits(self, n):
         """
         :type n: int
         :rtype: int
         """
         if n == 0:
             return 1
         digits = [9,9,8,7,6,5,4,3,2,1]
         ans = 0
         while n > 0:
             if n == 1:
                 ans += 10
             else:
                 res = 1
                 for i in range(n):
                     res *= digits[i]
                 ans += res
             n -= 1
         return ans

class Solution:
     def jump(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if len(nums) == 0 or len(nums) == 1:
             return 0;
         s = 0; e = 0; step = 0
         while (e < len(nums) - 1):
             fst = e
             step += 1
             for i in range(s, e + 1):
                 if fst < nums[i] + i:
                     fst = nums[i] + i
             s = e + 1
             e = fst
         return step

class Solution:
    def minEatingSpeed(self, piles: List[int], H: int) -> int:
        bananas = sum(piles)
        K = bananas // H + (bananas % H != 0)
        while True:
            hours_needed = 0
            for pile in piles:
                hours_needed += pile // K
                if pile % K != 0:
                    hours_needed += 1
            if hours_needed <= H:
                return K
            K += 1
