class Solution:
    def minEatingSpeed(self, piles: List[int], H: int) -> int:
        # use binary search to find the correct value
        maxPile = 0
        for i in piles:
            if i > maxPile:
                maxPile = i

        low = 1
        high = maxPile

        minVal = maxPile
        while low <= high:
            middle = (low + high) // 2
            numHours = 0
            for j in piles:
                numHours += j // middle
                if j % middle > 0:
                    numHours += 1

            if numHours <= H:
                minVal = middle
                high = middle - 1
            else:
                low = middle + 1

        return minVal
class Solution:
    def minEatingSpeed(self, piles: List[int], H: int) -> int:
        lo, hi = 1, max(piles)

        while lo<hi:
            mid=(lo+hi)//2

            cur_cap, num_hrs = 0, 0
            for p in piles:
                cur_cap = p
                if cur_cap<=mid:
                    num_hrs+=1
                else:
                    num_hrs+=(cur_cap//mid)+1

            if num_hrs>H:
                lo=mid+1
            else:
                hi=mid

        return lo

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:
        dist = [0.0]*n
        dist[start] = 1.0

        for i in range(n):
            flag = False
            for (a,b), p in zip(edges, succProb):
                if dist[a]==0.0 and dist[b]==0.0:continue
                Max = max(dist[a], dist[b])*p
                if Max > dist[a]:
                    dist[a] = Max
                    flag = True
                if Max > dist[b]:
                    dist[b] = Max
                    flag = True
            if not flag:
                break

        return dist[end]

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:
        # bfs only when prob is less than cur best add to the queue
        graph = [[] for _ in range(n)]
        for edge, p in zip(edges, succProb):
            a, b = edge
            graph[a].append((b, p))
            graph[b].append((a, p))
        prob = {start: 1}
        queue = [(start, 1)]
        while queue:
            new_queue = []
            for a, p_a in queue:
                for b, p_b in graph[a]:
                    p = p_a*p_b
                    if b not in prob or p > prob[b]:
                        prob[b] = p
                        new_queue.append((b, p))
            # print(prob)
            queue = new_queue
        return prob.get(end, 0)

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], probs: List[float], s: int, t: int) -> float:
        # first build the graph
        graph = {u: {} for u in range(n)}
        for (u, v), prob in zip(edges, probs):
            graph[u][v] = prob
            graph[v][u] = prob

        # run DFS/BFS search
        frontier = [s]
        path_probs = {u: 0 for u in range(n)}
        path_probs[s] = 1

        while len(frontier) != 0:
            u = frontier.pop(0)
            path_prob = path_probs[u]

            for v, edge_prob in graph[u].items():
                if path_prob * edge_prob > path_probs[v]:
                    path_probs[v] = path_prob * edge_prob
                    frontier.append(v)
        return path_probs[t]

class Solution:
    def maxProbability(self, n, edges, succProb, start, end) -> float:

        g    = [[] for _ in range(n)]
        prob = [0.  for _ in range(n)]

        prob[start] = 1.

        for (a,b), p in zip(edges, succProb):
            g[a].append((p, b))
            g[b].append((p, a))

        pq = [(-1., start)]

        while pq:
            p, v = heapq.heappop(pq)
            if prob[v] + p: continue

            if v == end:
                return prob[v]

            for ep, n in g[v]:
                _p = ep * prob[v]

                if _p > prob[n]:
                    prob[n] = _p
                    heapq.heappush(pq, (-_p, n))

        return 0

class Solution:
    def smallestDivisor(self, nums: List[int], threshold: int) -> int:
        l, r = 1, max(nums)
        while l < r:
            m = (l + r) // 2
            sum_num = 0
            for i in nums:
                sum_num += (i + m - 1) // m
            if sum_num > threshold:
                l = m + 1
            else:
                r = m
        return l

class Solution:
    def smallestDivisor(self, nums: List[int], threshold: int) -> int:
        l, r = 1, max(nums)
        count = 0
        while l < r:
            m = l + (r-l)//2
            for i in nums:
                count += (i + m -1) // m
            if count > threshold:
                l = m + 1
            else:
                r = m
            count = 0
        return l

class Solution:
    def smallestDivisor(self, nums: List[int], threshold: int) -> int:

        '''

        find m where    (num + m) // m    for all nums and sum to <= threshold

        '''

        i = 1
        j = max(nums)

        while i < j:
            m = (i + j) // 2

            total = 0
            for num in nums:
                total += (num + m - 1) // m  # ceil. division

            if total > threshold:
                i = m + 1
            elif total <= threshold:
                j = m

        return i

class Solution:
    def smallestDivisor(self, nums: List[int], threshold: int) -> int:

        '''

        find m where    (num + m) // m    for all nums and sum to <= threshold

        '''

        i = 1
        j = max(nums)
        m = (i + j) // 2

        ans = 0

        while i <= j:

            total = 0
            for num in nums:
                total += (num + m - 1) // m  # ceil. division

            if total > threshold:
                i = m + 1
            elif total <= threshold:
                j = m - 1
                ans = m

            m = (i + j) // 2  # mid point

        return ans

class Solution:

    def find(self, nums, div):
        ans = 0
        for i in nums:
            ans += i//div
            if i%div!=0:
                ans += 1
        return ans

    def smallestDivisor(self, nums: List[int], threshold: int) -> int:
        low = 1
        high = max(nums)
        while low<high:
            mid = (low+high)//2
            cur = self.find(nums, mid)
            if mid>1:
                prev = self.find(nums, mid-1)
            else:
                prev = 0
            if mid == 1 and cur<=threshold:
                return 1
            if cur<=threshold and prev>threshold:
                return mid
            elif cur>threshold:
                low = mid+1
            elif prev<=threshold:
                high = mid-1
        return (low+high)//2

class Solution:
     def wiggleMaxLength(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         n = len(nums)
         if n < 2: return n
         prev_diff = nums[1] - nums[0]
         count = 2 if prev_diff != 0 else 1
         for i in range(2, n):
             diff = nums[i] - nums[i-1]
             if (diff > 0 and prev_diff <= 0) or (diff < 0 and prev_diff >= 0):
                 count += 1
                 prev_diff = diff
         return count
