class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        def backtrack(ch_pos_to_end, num_choices, iter_idx, lhs, rhs):
            if ch_pos_to_end > len(result):
                return True

            mul = pow(10, ch_pos_to_end - 1)
            if iter_idx < len(words):
                word = words[iter_idx]
                idx = len(word) - ch_pos_to_end
                if idx >= 0:
                    if word[idx] not in num_mappings:
                        for n in num_choices:
                            if n == 0 and word[idx] == word[0]:
                                continue
                            num_mappings[word[idx]] = n
                            if backtrack(ch_pos_to_end, num_choices - {n}, iter_idx + 1,
                                         lhs + num_mappings[word[idx]] * mul,
                                         rhs):
                                return True
                            del num_mappings[word[idx]]
                    else:
                        return backtrack(ch_pos_to_end, num_choices, iter_idx + 1, lhs + num_mappings[word[idx]] * mul, rhs)
                else:
                    return backtrack(ch_pos_to_end, num_choices, iter_idx + 1, lhs, rhs)
            elif iter_idx == len(words):
                idx = len(result) - ch_pos_to_end
                if result[idx] not in num_mappings:
                    for n in num_choices:
                        if n == 0 and result[idx] == result[0]:
                            continue
                        new_rhs = rhs + n * mul
                        if not str(lhs).endswith(str(new_rhs)):
                            continue
                        num_mappings[result[idx]] = n
                        if backtrack(ch_pos_to_end + 1, num_choices - {n}, 0, lhs, new_rhs):
                            return True
                        del num_mappings[result[idx]]
                else:
                    added = num_mappings[result[idx]]
                    if not str(lhs).endswith(str(rhs + added * mul)):
                        return False
                    return backtrack(ch_pos_to_end + 1, num_choices, 0, lhs, rhs + added * mul)
            return False

        max_len_words = max([len(w) for w in words])
        if max_len_words > len(result):
            return False
        num_mappings = {}
        nums = {9, 8, 7, 6, 5, 4, 3, 2, 1, 0}
        return backtrack(1, nums, 0, 0, 0)

class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        max_len = len(result)
        if max(len(w) for w in words) > max_len:
            return False
        level = [[word[-i-1] for word in words if i<len(word)] for i in range(max_len)]
        level_set = [set([result[-i-1]] + level[i]) for i in range(max_len)]
        used_digits = set()
        nonzero_chars = set(word[0] for word in words + [result])
        assignments = {}
        def isSAT(eqn_index, carry):
            if eqn_index >= max_len:
                return carry == 0
            remaining_terms = []
            for t in level_set[eqn_index]:
                if t not in assignments:
                    for guess in range(t in nonzero_chars, 10):
                        if guess in used_digits:
                            continue
                        assignments[t] = guess
                        used_digits.add(guess)
                        if isSAT(eqn_index, carry):
                            return True
                        del assignments[t]
                        used_digits.remove(guess)
                    return False

            s = sum(assignments[c] for c in level[eqn_index]) + carry
            if s % 10 != assignments[result[-eqn_index-1]]:
                return False
            return isSAT(eqn_index +1, s // 10)

        return isSAT(0, 0)

class Solution:
    def knightDialer(self, n: int) -> int:
        if n == 1: return 10
        self.mod = 1e9 + 7
        self.cache = {}
        self.knight_steps = {
            1: [6, 8],
            2: [7, 9],
            3: [4, 8],
            4: [0, 3, 9],
            5: [],
            6: [1, 7, 0],
            7: [2, 6],
            8: [1, 3],
            9: [2, 4],
            0: [4, 6]
        }
        count = 0
        for i in range(10):
            count += self.recursive_calc(i, n - 1) 
            count = count % self.mod

        # print(self.cache)
        return int(count % self.mod)


    def recursive_calc(self, current_number, steps):
        if steps == 0: return 1
        if (current_number, steps) in self.cache:
            return self.cache[(current_number, steps)]
        total = 0
        for i in self.knight_steps[current_number]:
            total += self.recursive_calc(i, steps - 1)
            total = total % self.mod
        self.cache[(current_number, steps)] = total
        return self.cache[(current_number, steps)]

class Solution:
    def knightDialer(self, n: int) -> int:
        if n == 1:
            return 10
        x0,x1,x2,x3,x4,x5,x6,x7,x8,x9 = 1,1,1,1,1,0,1,1,1,1
        for i in range(1, n):
            x0,x1,x2,x3,x4,x6,x7,x8,x9 = x4+x6,x6+x8,x7+x9,x4+x8,x0+x3+x9,x0+x1+x7,x2+x6,x1+x3,x2+x4
        return (x1+x2+x3+x4+x5+x6+x7+x8+x9+x0)%(10**9+7)

class Solution:

    BASE = 10 ** 9 + 7

    def knightDialer(self, N: int) -> int:
        if N <= 1:
            return 10
        a, b, c, d = 2, 4, 2, 1
        for _ in range(N - 1):
            a, b, c, d = (b, 2 * (a + c) % self.BASE, (b + 2 * d) % self.BASE, c)
        return (a + b + c + d) % self.BASE

class Solution:
    def maxLength(self, arr: List[str]) -> int:
        d = ['']
        for a in arr:
            if len(set(a)) < len(a):
                continue
            else:
                for x in d:
                    if set(x) & set(a):
                        continue
                    else:
                        t = set(a) | set(x)
                        d.append(t)
        max = 0
        for i in d:
            if len(i) > max:
                max = len(i)
        return max

class Solution:
    def maxLength(self, arr: List[str]) -> int:
        if len(arr)==1:
            if len(set(arr[0]))==len(arr[0]):
                return len(arr[0])
            else:
                return 0

        new_arr = []
        for s in arr:
            if len(s) == len(set(s)):
                new_arr.append((set(s), len(s)))

        if not new_arr:
            return 0
        # print(new_arr)
        ans = 0

        def backtrack(ind, temp, temp_sum):
            nonlocal ans
            if temp_sum > ans:
                ans = temp_sum

            for i in range(ind, len(new_arr)):
                if not (new_arr[i][0] & temp):
                    backtrack(i+1, temp | new_arr[i][0], temp_sum+new_arr[i][1])
                else:
                    backtrack(i+1, temp, temp_sum)

        backtrack(0, set(), 0)
        return ans

class Solution:
    def maxLength(self, arr: List[str]) -> int:
        dp = [set()]
        length = 0
        for word in arr:
            if len(word) != len(set(word)): continue
            curr = set(word)
            for used in dp[:]:
                if not len(used & curr):
                    dp.append(used | curr)
                    length = max(length,  len(used | curr))
        return length

class Solution:
    # https://leetcode.com/problems/maximum-length-of-a-concatenated-string-with-unique-characters/discuss/631245/Python-3-Easy-Code-Intutive-Solution

    def maxLength(self, arr: List[str]) -> int:
        res = 0
        unique = ['']

        def isvalid(s):
            return len(s) == len(set(s))

        for word in arr:
            for u in unique:
                tmp = word + u
                if isvalid(tmp):
                    unique.append(tmp)
                    res = max(res, len(tmp))

        return res

class Solution:
    def maxLength(self, arr):
        prev = {0: 0}
        for word in arr:
            seen = 0
            duplicate = False
            for char in word:
                binaryC = 1 << (ord(char) - ord('a'))
                if binaryC & seen != 0:
                    duplicate = True
                    break
                else:
                    seen |= binaryC
            if duplicate:
                continue
            toAdd = dict()
            for k in prev:
                if k & seen == 0:
                    toAdd[k | seen] = prev[k] + len(word)
            prev.update(toAdd)
        return max(prev.values())

class Solution:
    def maxLength(self, arr):
        cands = {0: 0}
        for word in arr:
            if len(word) != len(set(word)): continue
            currW = sum(1 << (ord(char) - ord('a')) for char in word)
            toAdd = dict()
            for prevW in cands:
                if prevW & currW == 0:
                    toAdd[prevW + currW] = cands[prevW] + len(word)
            cands.update(toAdd)
        return max(cands.values())

