class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        locked_boxes = set()
        unused_keys = set()
        candy_count = 0
        cur_box = []

        for box in initialBoxes:
            if status[box] or box in unused_keys:
                candy_count += candies[box]
                for i in keys[box]:
                    if not status[i]:
                        if i not in locked_boxes:
                            unused_keys.add(i)
                        else:
                            locked_boxes.remove(i)
                            cur_box.append(i)
                for i in containedBoxes[box]:
                    if not status[i] and i not in unused_keys:
                        locked_boxes.add(i)
                    else:
                        cur_box.append(i)
                        if i in unused_keys:
                            unused_keys.remove(i)
                if box in unused_keys:
                    unused_keys.remove(box)
            else:
                locked_boxes.add(box)

        while cur_box:
            box = cur_box.pop()
            candy_count += candies[box]
            for i in keys[box]:
                if not status[i]:
                    if i not in locked_boxes:
                        unused_keys.add(i)
                    else:
                        locked_boxes.remove(i)
                        cur_box.append(i)
            for i in containedBoxes[box]:
                if not status[i] and i not in unused_keys:
                    locked_boxes.add(i)
                else:
                    cur_box.append(i)
                    if i in unused_keys:
                        unused_keys.remove(i)
            if box in unused_keys:
                unused_keys.remove(box)

        return candy_count

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        n = len(status)
        visited = [0] * n
        unopened = [0] * n
        opened = []

        ans = 0
        for b in initialBoxes:
            if status[b] == 1:
                opened.append(b)
                visited[b] = 1
            else:
                unopened[b] = 1
        while opened:
            q2 = []
            for b in opened:
                ans += candies[b]
                for bb in containedBoxes[b]:
                    if visited[bb] == 0:
                        if status[bb] == 1:
                            q2.append(bb)
                        else:
                            unopened[bb] = 1
                for k in keys[b]:
                    status[k] = 1
                    if unopened[k] == 1 and visited[k] == 0:
                        unopened[k] = 0
                        visited[k] = 1
                        q2.append(k)
            opened = q2
        return ans

class Solution:
    dp = {0: 0}
    def racecar(self, target: int) -> int:
        if target in self.dp:
            return self.dp[target]
        n = target.bit_length()
        if 2**n - 1 == target:
            self.dp[target] = n
        else:
            self.dp[target] = self.racecar(2**n - 1 - target) + n + 1
            for m in range(n - 1):
                self.dp[target] = min(self.dp[target], self.racecar(target - 2**(n - 1) + 2**m) + n + m + 1)
        return self.dp[target]

class Solution:
  def __init__(self):
    self.dp = {0: 0}

  def racecar(self, t: int) -> int:
    if t in self.dp:
      return self.dp[t]
    n = t.bit_length()
    if 2**n - 1 == t:
      self.dp[t] = n
    else:
      # go pass via n A's, then turn back
      self.dp[t] = self.racecar(2**n - 1 - t) + n + 1
      # stop after (n - 1) A's, turn back, go m A's, then turn back
      for m in range(n - 1):
        self.dp[t] = min(self.dp[t], self.racecar(t - 2**(n - 1) + 2**m) + n + m + 1)
    return self.dp[t]

