        cnt, N = 0, len(light)
        bulbs = [0] * N
        for i, pos in enumerate(light, start = 1):
            pos -= 1
            if sum(bulbs[:pos]) == 2 * pos:
                bulbs[pos] = 2
                while pos + 1 < N and bulbs[pos+1] == 1:
