        d1 = sorted([i for i in d if i%3 ==1])
        d2 = sorted([i for i in d if i%3 ==2])
        d3 = [i for i in d if i%3 ==0]
        if sum(d) % 3 == 1:
            if len(d1) != 0:
                res = d1[1:] + d2 + d3
            else:
                res = d2[2:]+ d3
        elif sum(d) % 3 == 2:
