class Solution:
    def largestMultipleOfThree(self, digits: List[int]) -> str:
        dic=defaultdict(list)
        for d in digits:dic[d%3].append(d)
        arr=[]
        n1=len(dic[1])
        n2=len(dic[2])
        arr+=dic[0]
        if n1%3==n2%3==0 or n1==n2:arr+=dic[1]+dic[2]
        else:
            dic[1].sort(reverse=1)
            dic[2].sort(reverse=1)
            l1=l2=0
            if n1%3==2 and n2==3:
                while n2>3:
                    l2+=3
                    n2-=3
                l1+=n1//3*3
                l1+=2
                l2+=2
            elif n2%3==2 and n1==3:
                while n1>3:
                    l1+=3
                    n1-=3
                l2+=n2//3*3
                l2+=2
                l1+=2
            else:
                if n1>2:
                    l1+=n1//3*3
                    n1-=n1//3*3
                if n2>2:
                    l2+=n2//3*3
                    n2-=n2//3*3
                if n1!=0 and n2!=0:
                    min1=min(n1,n2)
                    l1+=min1
                    l2+=min1
            arr+=dic[1][:l1]+dic[2][:l2]
        arr.sort(reverse=1)
        if arr and arr[0]==0:return '0'
        return ''.join(str(i) for i in arr)

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        memo = {}

        def cost(s,i,j): #calculate the cost of transferring one substring into palindrome string
            r = 0
            while i < j:
                if s[i] != s[j]:
                    r += 1
                i += 1
                j -= 1
            return r

        def dfs(i, k):
            if (i, k) in memo: return memo[(i, k)]
            if (n - i) == k: return 0
            if k == 1: return cost(s, i, n-1)
            res = n + 1 
            for j in range(i+1, n-k + 2):
                res = min(res, dfs(j, k-1) + cost(s, i, j-1))
            memo[(i, k)] = res 
            return res

        return dfs(0 , k)
class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        sLen = len(s)

        dp = {}

        def moveOnce(prei, i0, k0):
            if (prei, i0, k0) in dp:
                return dp[(prei, i0, k0)]
            if k0 == k:
                l = prei
                r = sLen -1
                subAns = 0
                while r > l:
                    if s[r] != s[l]:
                        subAns += 1
                    r -= 1
                    l += 1
                dp[(prei, i0, k0)] = subAns
                return subAns

            l = prei
            r = i0
            subAns = 0
            while r > l:
                if s[r] != s[l]:
                    subAns += 1
                r -= 1
                l += 1             
            if sLen - i0 - 1 <= k - k0:
                return subAns
            subAns = min(subAns + moveOnce(i0+1, i0+1,k0+1), moveOnce(prei, i0+1, k0))
            dp[(prei, i0, k0)] = subAns
            return subAns

        return moveOnce(0, 0, 1)


class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n=len(s)

        memo={}

        def cost(i,j):
            r = 0
            while i < j:
                if s[i] != s[j]:
                    r += 1
                i += 1
                j -= 1
            return r

        def divide(st,d):

            if (st,d) in memo:
                return memo[(st,d)]

            if d==n-st:
                return 0

            if d==1:
                return cost(st,n-1)

            ans=float('inf')

            for i in range(st+1,n-d+2):
                ans=min(ans,cost(st,i-1)+divide(i,d-1))

            memo[(st,d)]=ans

            return ans


        return divide(0,k)
class Solution1:
    def palindromePartition(self, s: str, k: int) -> int:
        dp = [[0] * len(s) for i in range(len(s))]

        n = len(s)

        def transferPalimCount(s) -> int:
            res = 0
            q = len(s) - 1
            p = 0

            while p < q:
                if s[p] != s[q]:
                    res += 1
                p += 1
                q -= 1
            return res

        for i in range(n):
            for j in range(i, n):
                dp[i][j] = transferPalimCount(s[i:j+1])



        def findMin(s, e, k, count, candidates):
            if k == 0:
                if s > e:
                    candidates.append(count)
                    return
                else:
                    count += dp[s][e]
                    candidates.append(count)
                    return

            # string is not able to split to too much parts
            if e-s+1 < k+1:
                return

            for i in range(s, e+1):
                findMin(i+1, e, k-1, count + dp[s][i], candidates)

        candidates = []
        findMin(0, n-1, k-1, 0, candidates)

        return min(candidates)

