class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s)!=len(t):
            return False

        hash_map = {}
        for i in range(len(s)):
            if s[i]!=t[i]:
                diff = -1*(ord(s[i])-ord(t[i]))
                if diff<0:
                    diff = 26+diff
                if diff in hash_map:
                    hash_map[diff]+=1
                    diff += (hash_map[diff]-1)*26
                else:
                    hash_map[diff] = 1
                if diff>k:
                   return False
        return True

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:

        if len(s) != len(t): return False
        mp = {}
        for i in range(len(s)): 
            v =  ord(t[i]) - ord(s[i])
            if v == 0: 
                continue
            if v < 0: 
                v += 26 # shift backward
            if v > k: 
                return False
            if v in mp: 
                # the highest number
                high_v = mp[v] + 26
                if high_v > k: 
                    return False
                mp[v] = high_v
            else:
                mp[v] = v

        return True
class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t): return False #edge case 

        visited = {}
        for ss, tt in zip(s, t):
            if ss != tt: 
                d = (ord(tt) - ord(ss)) % 26 #distance 
                if d not in visited: 
                    visited[d] = d
                else: 
                    visited[d] += 26 
                if visited[d] > k: 
                    return False 
        return True 
class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False

        alreadySeen = {}

        for i in range(len(s)):
            if s[i] != t[i]:
                difference = (ord(t[i]) - ord(s[i])) % 26

                if difference > k:
                    return False

                if difference not in alreadySeen:
                    alreadySeen[difference] = 1
                else:
                    newDifference = difference + alreadySeen[difference] * 26

                    if newDifference > k:
                        return False
                    else:
                        alreadySeen[difference] += 1

        return True
