         if n <= 0:
             return 0
         diag_lr = [True] * (2*n-1)
         diag_rl = [True] * (2*n-1)
         vert = [True] * n
         res = []

         def _check_board(x, y):
             return vert[y] and diag_lr[y-x+n-1] and diag_rl[x+y]

         def _helper(x):
             if x == n:
                 res.append(1)
