class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        ages = sorted(ages)
        res = 0
        prev = None
        for i in range(len(ages) - 1, -1, -1):
            if i == len(ages) - 1 or ages[i] != ages[i + 1]:
                prev = i
            low ,right = 0 ,prev - 1
            while low < right:
                mid = (low + right)//2
                if ages[mid] <= 0.5*ages[i] + 7:
                    low = mid + 1
                else:
                    right = mid
            if ages[low] >  0.5 * ages[i] + 7:
                res += (prev - low)
        return res

class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        N = len(text)
        s = set()

        for offset in range(1, N // 2 + 1):
            K = 0
            for j in range(N - offset):
                if text[j] == text[j+offset]:
                    K += 1
                else:
                    K = 0
                if K >= offset:
                    s.add(text[j-offset+1:j+offset+1])
        return len(s)

