class Solution:
    def soupServings(self, N: int) -> float:
        compressed_N = N // 25
        N = compressed_N + (1 if (N-compressed_N*25)>0 else 0)

        mem = {}

        def dp(a, b):
            if (a, b) in mem:
                return mem[(a,b)]
            else:
                if a <= 0 or b <= 0:
                    result = 0.5 if a <=0 and b <= 0 else 1.0 if a <= 0 else 0.0
                else:
                    result = 0.25 * (dp(a-4, b) + dp(a-3, b-1) + dp(a-2, b-2) + dp(a-1, b-3))
                mem[(a,b)] = result
                return result

        if N <= 100:
            return dp(N, N)
        else:
            for i in range(100, N+1):
                current_result = dp(i, i)
                if 1 - current_result < 1e-6:
                    return 1.0
            return current_result

class Solution:
    def soupServings(self, N: int) -> float:
        if N > 5555:
            return 1

        memo = dict()
        def Pa(A, B):
            if (A, B) in memo:
                return memo[(A, B)]
            if A <= 0 and B <= 0:
                return 0.5
            if A <= 0:
                return 1
            if B <= 0:
                return 0
            else:
                memo[(A, B)] = (Pa(A-100, B) + Pa(A-75, B-25) + Pa(A-50, B-50) + Pa(A-25, B-75)) / 4
                return memo[(A, B)]

        return Pa(N, N)

class Solution:
    def soupServings(self, N: int) -> float:
        seen={}
        def find_prob(A,B):
            if A==0 and B==0:
                return 0.5
            if A==0:
                return 1
            if B==0:
                return 0
            if (A,B) in seen:
                return seen[A,B]
            temp=0
            for x,y in [[100,0],[75,25],[50,50],[25,75]]:
                temp+=find_prob(A-x if A>x else 0,B-y if B>y else 0)
            seen[A,B]=0.25*temp
            return 0.25*temp
        if N>4800: return 1.0
        return find_prob(N,N)

