            postsum += stoneValue[i]
            dp[i] = postsum - min(dp[i+1], dp[i+2], dp[i+3])
        alice, bob = dp[0], postsum - dp[0]
        if alice == bob:
            return 'Tie'
        if alice > bob:
            return 'Alice'
        return 'Bob'

