     def convert(self, s, numRows):
         """
         :type s: str
         :type numRows: int
         :rtype: str
         """
         if len(s) == 0 or numRows < 1:
             return ''
         if numRows == 1:
             return s
         maxStep = (numRows-1)*2
         reStr = ''
         for i in range(numRows):
