class Solution:
    def tallestBillboard(self, rods: List[int]) -> int:
        rods.sort(reverse=True)
        n = len(rods)
        dp = [0 for i in range(n)]
        rsum = 0
        self.result = 0

        for i in range(n-1, -1, -1):
            rsum += rods[i]
            dp[i] = rsum


        def dfs(idx, lsum, rsum):
            if idx >= n:
                if lsum == rsum:
                    self.result = max(self.result, lsum)
                return

            if abs(lsum-rsum) >  dp[idx]:
                return
            if lsum+rsum+dp[idx] <= 2 * self.result:
                return

            dfs(idx+1, lsum+rods[idx], rsum)
            dfs(idx+1, lsum, rsum+rods[idx])
            dfs(idx+1, lsum, rsum)

        dfs(0, 0, 0)
        return self.result

class Solution:
    def exclu(self,nums):
        # whether we can find two elements x and y in nums so that x & y == 0
        n=len(nums)
        if n<=1: return False
        if n<=4:
            for x in nums:
                for y in nums:
                    if x & y ==0: return True
            return False

        set0,set1=set(),set()
        for x in nums:
            if x & 1 : set1.add(x>>1)
            else: set0.add(x>>1)
        if set0:
            if self.exclu(set0): return True
            if set1:  return self.exclu2(set0,set1)
        return False

    def exclu2(self,set0,set1):
        # whether we can find x in set0 and y in set1 so that x & y == 0
        # set0 and set1 are not empty
        if len(set0)==0 or len(set1)==0: return False
        if len(set1)==1:
            x=next(iter(set1))
            for y in set0: 
                if x & y ==0: return True
            return False

        if len(set0)==1:
            x=next(iter(set0))
            for y in set1: 
                if x & y ==0: return True
            return False

        if len(set0)<=8 and len(set1)<=8:
            for x in set0:
                for y in set1:
                    if x & y ==0: return True
            return False

        set00,setx0,set01,set11=set(), set(), set(), set() 
        for x in set0:
            setx0.add(x>>1)
            if x & 1 ==0: set00.add(x>>1)
        for x in set1:
            if x & 1 : set11.add(x>>1)
            else: set01.add(x>>1)

        if set00 and set11 and self.exclu2(set00,set11): return True
        if set01 and setx0 and self.exclu2(set01,setx0): return True
        return False

