class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:

        def twoProduct(arr, target):
            # returns the count of pairs in arr whose product equals target
            # twoProduct([2,3,1,3,4,6], 6) => 3
            d = {}
            ret = 0
            for x in arr:
                if target % x == 0 and target // x in d:
                    ret += d[target//x]
                if x in d:
                    d[x] += 1
                else:
                    d[x] = 1
            return ret

        ret = 0
        for x in nums1:
            sq = x**2
            ret += twoProduct(nums2, sq)
        for x in nums2:
            sq = x**2
            ret += twoProduct(nums1, sq)
        return ret
class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        return self.helper(nums1, nums2) + self.helper(nums2, nums1)

    def helper(self, arr1, arr2):
        res = 0
        for num in arr1:
            res += self.twoProduct(num * num, arr2)
        return res

    def twoProduct(self, target, arr):
        visited = {}
        res = 0
        for num in arr:
            if not num:
                continue
            if target % num == 0 and target // num in visited:
                res += visited[target // num]
            if num not in visited:
                visited[num] = 1
            else:
                visited[num] += 1
        return res

