class Solution:
     def numSquares(self, n):
         """
         四平方和定理
         :type n: int
         :rtype: int
         """
         while n % 4 == 0:
             n //= 4
         if n % 8 == 7:
             return 4
         for i in range(n+1):
             tmp = i * i
             if tmp <= n:
                 if int((n-tmp) ** 0.5) ** 2 + tmp == n:
                     return 1 + (0 if tmp == 0 else 1)
             else:
                 break
         return 3

class Solution:
     def numSquares(self, n):
         """
         :type n: int
         :rtype: int
         """
         def is_square(n):
             return int(n**0.5) * int(n**0.5) == n

         if is_square(n): return 1
         for i in range(1, int((n**0.5) + 1)):
             if is_square(n - i*i):
                 return 2
         while (n & 3) == 0: n >>= 2
         if n & 7 == 7: return 4
         return 3

class Solution:
    def minDeletionSize(self, A: List[str]) -> int:
        size = len(A[0])
        best = [0] * size
        best[0] = 1
        for i in range(1, size):
            best[i] = 1
            for j in range(0, i):
                if best[j] >= best[i] and self.beats(A, i, j):
                    best[i] = best[j] + 1

        return size - max(best)


    def beats(self, A, a, b):
        # Returns True if idx a beats idx b
        for s in A:
            if s[b] > s[a]:
                return False

        return True

