class Solution:
    def subarraysWithKDistinct(self, A: List[int], K: int) -> int:
        if K > len(A):
            return 0

        result = checker = windowStart = 0
        hashMap = {}
        a_length = len(A)

        for windowEnd in range(a_length):
                curr_digit = A[windowEnd]
                if curr_digit in hashMap:
                    hashMap[curr_digit] += 1
                else:
                    hashMap[curr_digit] = 1

                if len(hashMap) > K:
                    del hashMap[A[checker]]
                    checker += 1
                    windowStart = checker
                if len(hashMap) == K:
                    while hashMap[A[checker]] > 1:
                        hashMap[A[checker]] -= 1
                        checker += 1
                    result += checker - windowStart +1
        return result

class Solution:
    def subarraysWithKDistinct(self, A: 'List[int]', K: 'int') -> 'int':
        freq = {}
        start = 0
        start_k = 0
        res = 0
        for i, x in enumerate(A):
            freq[x] = freq.get(x, 0) + 1
            if len(freq) == K + 1:
                # remove the distinct at start_k, move start_k, start
                del freq[A[start_k]]
                start_k += 1
                start = start_k
            if len(freq) == K:
                # update start_k and res (Notice: K >= 1)
                while freq[A[start_k]] > 1:
                    freq[A[start_k]] -= 1
                    start_k += 1
                res += start_k - start + 1
        return res

