        nums.sort()
        ans = 0
        M = 10 ** 9 + 7
        l, r = 0, len(nums) - 1
        while l <= r:
            if nums[l] + nums[r] > target:
                r -= 1
            else:
                ans += 2 ** (r - l)
                l += 1
        return ans % M

