                        remove = (dp[diff-1][6] - dp[diff-1][j] + mod)%mod
                        dp[i][j] = (dp[i - 1][6] - remove + mod)%mod
                    else:
                        dp[i][j] = (dp[i - 1][6] - 1)%mod

                    sumi = (sumi + dp[i][j])%mod
            dp[i][6] = sumi

        return dp[n-1][6]

class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        if n == 1:
            return 6
        mem = {}
        def get_dp(n, d, c):
            if n==1:
                return 6 if c < rollMax[d-1] else 5
            elif (n, d, c) not in mem:
                mem[n, d, c] = 0
                for d_ in range(1, 7):
                    if d_ != d:
                        mem[n, d, c] += get_dp(n-1, d_, 1)
                    elif c < rollMax[d-1]:
                        mem[n, d, c] += get_dp(n-1, d, c+1)
            return mem[n, d, c]
        result = sum(get_dp(n-1, d, 1) for d in range(1, 7))
        result = result % int(10**9+7)
        return result

class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        dp = [[1 for _ in range(6)] for _ in range(n)]

        for i in range(1, n):
            for j in range(6):
                inc = sum(dp[i-1])
                prev = i - rollMax[j] - 1
                if prev == -1:
                    inc -= 1
                elif prev >= 0:
                    for k in range(6):
                        if k == j:
                            continue
                        inc -= dp[prev][k]
                dp[i][j] = inc
        # print(dp)
        return sum(dp[-1]) % (10 ** 9 + 7)

class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        # dynamic programming
        # dp[i][j]: num of seqs for i + 1 rolls that ends at face j + 1
        dp = [[0 for c in range(6)] for r in range(n)]
        # initialize
        for c in range(6):
            dp[0][c] = 1
        # fill in dp by rows
        for r in range(1, n):
            for c in range(6):
                if r < rollMax[c]:
                    dp[r][c] = sum(dp[r-1])
                else:
                    for prev in range(r - rollMax[c], r):
                        dp[r][c] += sum(dp[prev]) - dp[prev][c]
        return sum(dp[-1]) % 1000000007

class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        memo = [[0] * 7 for _ in range(n + 1)]
        for j in range(6):
            memo[1][j] = 1
            memo[1][-1] += memo[1][j]
        for i in range(2, n + 1):
            for j in range(6):
                memo[i][j] = memo[i - 1][-1]
                k = i - rollMax[j]
                if k == 1: memo[i][j] -= 1
                elif k > 1: memo[i][j] -= (memo[k - 1][-1] - memo[k - 1][j])
                memo[i][-1] += memo[i][j]
        return memo[n][6] % int(1e9 + 7)

