        for (i, j) in itertools.permutations(list(range(n)), 2):
            extra[i][j] = extra_to_append(A[i], A[j])

        dp = [[''] * n for _ in range(1 << n)]
        ret = ''
        for mask in range(1, 1 << n):
            for (ci, cw) in enumerate(A):
                if not mask & (1 << ci):
                    continue
                pre_mask = mask & (~(1 << ci))
                if not pre_mask:
                    dp[mask][ci] = cw
                else:
                    for (pi, pw) in enumerate(A):
                        if not pre_mask & (1 << pi):
                            continue
                        if not dp[mask][ci] or len(dp[mask][ci]) > len(dp[pre_mask][pi]) + len(extra[pi][ci]):
                            dp[mask][ci] = dp[pre_mask][pi] + extra[pi][ci]
                if mask == (1 << n) - 1:
                    ret = dp[mask][ci] if not ret or len(ret) > len(dp[mask][ci]) else ret

        return ret
class Solution:
    def shortestSuperstring(self, A: List[str]) -> str:
        n = len(A)
        self.cost = [[0 for j in range(n)] for i in range(n)]
        for i in range(n):
            for j in range(n):
                w1 = A[i]
                w2 = A[j]
                k = min(len(w1), len(w2))
                while k > 0:
                    if w1[-k:] == w2[:k]:
                        break
                    k -= 1

                self.cost[i][j] = k

        self.cache = {}
        ans = ''
        for i in range(n):
            candidate = self.dfs(A, i, (1 << n) - 1)
            if ans == '' or len(candidate) < len(ans):
                ans = candidate

        return ans

    def dfs(self, A, index, cur):
        if (index, cur) in self.cache:
            return self.cache[(index, cur)]

        if not ((1 << index) & cur):
            return ''

        if cur == (1 << index):
            return A[index]

        self.cache[(index, cur)] = ''
        for i in range(len(A)):
            if i == index or not ((1 << i) & cur):
                continue

            temp = self.dfs(A, i, cur - (1 << index)) + A[index][self.cost[i][index]:]
            if self.cache[(index, cur)] == '' or len(temp) < len(self.cache[(index, cur)]):
                self.cache[(index, cur)] = temp

        return self.cache[(index, cur)]
class Solution:
    def shortestSuperstring(self, A: List[str]) -> str:
        def cost(a, b):
            alen, blen = len(a), len(b)
            minlen = min(alen, blen)
            for i in range(minlen - 1,0,-1):
                if a[alen - i:] == b[:i]:
                    return blen - i
            return blen
        n = len(A)
        g = [[-1] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if j == i: continue
                g[i][j] = cost(A[i],A[j])

        dp = [[float('inf')] * n for _ in range(1<<n)]
        parent = [[-1] * n for _ in range(1<<n)]
        anslen = float('inf')
        cur = -1
        ans = ''
        for i in range(n):
            dp[1<<i][i] = len(A[i])
        for s in range(1, 1<<n):
            for j in range(n):
                if (s & (1<<j)) == 0: continue
                ps = s & ~(1 << j)
                for i in range(n):
                    if i == j: continue
                    if dp[s][j] > dp[ps][i] + g[i][j]:
                        dp[s][j] = dp[ps][i] + g[i][j]
                        parent[s][j] = i

        for i in range(n):
            if anslen > dp[(1<<n)-1][i]:
                anslen = dp[(1<<n)-1][i]
                cur = i
        s = (1 << n) - 1
        while s > 0:
            ps = s & ~(1 << cur)
            parent_node = parent[s][cur]
            if ps == 0:
                ans = A[cur] + ans
            else:
                curstr = A[cur]
                ans = curstr[len(curstr) - g[parent_node][cur]:] + ans
            s = ps
            cur = parent_node
        return ans
class Solution:
    def shortestSuperstring(self, A: List[str]) -> str:
        size = len(A)
        costs = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                if i == j: 
                    costs[i][j] = 0
                    continue
                wi, wj = A[i], A[j]
                si, sj = len(wi), len(wj)
                costs[i][j] = sj
                for k in range(1, min(si, sj) + 1):
                    if wi[-k:] == wj[:k]:
                        costs[i][j] = sj - k
        dp = [[20 * 12] * size for _ in range(1 << size)]
        parent = [[-1] * size for _ in range(1 << size)]
        for i in range(size):
            dp[1 << i][i] = len(A[i])
        for state in range(1, 1 << size):
            for i in range(size):
                if state & (1 << i) == 0: continue
                prev = state - (1 << i)
                for j in range(size):
                    if prev & (1 << j) == 0: continue
                    if dp[state][i] > dp[prev][j] + costs[j][i]:
                        dp[state][i] = dp[prev][j] + costs[j][i]
                        parent[state][i] = j
        minCost = min(dp[-1])
        index = dp[-1].index(minCost)
        res = ''
        state = (1 << size) - 1
        while state:
            prevIndex = parent[state][index]
            if prevIndex < 0: res = A[index] + res
            else:
                cost = costs[prevIndex][index]
                res = A[index][-cost:] + res
            state -= 1 << index
            index = prevIndex
        return res
class Solution:
    def shortestSuperstring(self, A: List[str]) -> str:
        N = len(A)
        def Cost(x, y):
            cost = len(y)
            max_similarity = 0
            for i in range(1, min(len(x), len(y))):
                if x[-i:] == y[:i]: max_similarity = i
            return cost - max_similarity

        g = [[float('inf')] * N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                if i != j:
                    cost = Cost(A[i], A[j])
                    g[i][j] = cost
                else: g[i][j] = len(A[i])

        dp = [[float('inf')] * N for _ in range(1<<N)]
        parent = [[-1] * N for _ in range(1<<N)]

        for i in range(N):
            dp[1<<i][i] = len(A[i])

        for s in range(1, 1<<N):
            for i in range(N):
                if s & (1<<i):  #valid dp[s][i] check
                    prev = s - (1<<i)
                    for j in range(N):
                        if j != i and prev & (1<<j):
                            cur_cost = dp[prev][j] + g[j][i]
                            if cur_cost < dp[s][i]:
                                dp[s][i] = cur_cost
                                parent[s][i] = j

        min_cost = float('inf')
        ind = -1
        last_row = dp[2**N - 1]
        for i in range(N):
            if last_row[i] < min_cost:
                min_cost = last_row[i]
                ind = i

        s = 2**N - 1
        res = A[ind]
        child_ind = ind
        # print(s, ind)
        ind = parent[s][ind]
        s = s - (1<<child_ind)
        while s and ind >= 0:
            cost = g[ind][child_ind]
            pre_len = len(A[ind]) - len(A[child_ind]) + g[ind][child_ind]
            res = A[ind][:pre_len] + res
            child_ind = ind
            # print(s, ind)
            ind = parent[s][ind]
            s = s - (1<<child_ind)

        return res

