class Solution:
     def maximumGap(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if len(nums) < 2:
             return 0

         if len(nums) == 2:
             return abs(nums[0] - nums[1])

         left, right = min(nums), max(nums)
         brng = (right - left) // (len(nums) - 1) + 1
         bnum = (right - left) // brng + 1
         bucket = [None] * bnum
         for x in nums:
             idx = (x - left) // brng
             if bucket[idx]:
                 bucket[idx] = (min(bucket[idx][0], x), max(bucket[idx][1], x))
             else:
                 bucket[idx] = (x, x)

         max_gap = pre = 0
         for cur in range(1, bnum):
             if not bucket[cur]:
                 continue
             max_gap = max(max_gap, bucket[cur][0] - bucket[pre][1])
             pre = cur

         return max_gap

class Solution:
     def maximumGap(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if len(nums)<2:
             return 0

         m = 0
         for num in nums:
             m = max(m, num)

         exp = 1
         while m//exp:
             aux = [[] for i in range(10)]
             for num in nums:
                 aux[(num//exp)%10].append(num)
             index = 0
             for item in aux:
                 if len(item)!=0:
                     for i in item:
                         nums[index] = i
                         index += 1
             exp *= 10

         maxGap = 0
         pre = nums[0]
         for num in nums:
             maxGap = max(maxGap, num - pre)
             pre = num
         return maxGap

class Solution:
    def minScoreTriangulation(self, A: List[int]) -> int:
        N = len(A)
        if N == 3: return A[0]*A[1]*A[2]

        def solver(s,t, A):
            if t-s+1 < 3: return 0

            if dp[s][t] != float('inf'): return dp[s][t]


            for i in range(s+1, t):
                dp[s][t] = min(dp[s][t], solver(s,i, A) + A[s]*A[i]*A[t] + solver(i,t, A))

            return dp[s][t]

        dp = []
        for i in range(N):
            dp.append([float('inf')]*N)


        return solver(0,N-1,A)

