class Solution:
    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        def compute_gcd(x, y):
            if y == 0: return x
            return compute_gcd(y, x%y)

        # This function computes LCM
        def compute_lcm(x, y):
            lcm = (x*y)//compute_gcd(x,y)
            return lcm


        C = compute_lcm(A,B)
        l = min(A,B)
        h = N*max(A,B)
        #print(C)
        while (l < h):
            mid = (l+h)//2
            m = mid//A + mid//B - mid//C
            if m>=N:
                h = mid
            else:
                l = mid + 1
        return l %(10**9+7)

class Solution:
    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        d = gcd(A, B)
        A //= d
        B //= d

        def how_many_below(n):
            return n//A+n//B-n//(A*B)

        lo = N-1
        hi = min(A, B)*N

        while hi - lo > 1:
            h = (hi+lo)//2
            if how_many_below(h) >= N:
                hi = h
            else:
                lo = h
        return hi*d % (10**9+7)


