class Solution:
    def countVowelPermutation(self, n: int) -> int:
        if n == 1:
            return 5
        a, e, o, u, i = 1, 1, 1, 1, 1
        for _ in range(1, n):
            a, e, o, u, i = e + u + i, i + a, i, i + o, e + o
        return (a + e + o + u + i) % (10**9 + 7)

class Solution:
    def countVowelPermutation(self, n: int) -> int:
        if n <= 1:
            return n * 5
        start_table = {0: [1], 1: [0, 2], 2: [0, 1, 3, 4], 3: [2, 4], 4: [0]}
        dp = [[0] * 5 for i in range(n + 1)]
        for i in range(5):
            dp[1][i] = 1
        for i in range(2, n+1):
            for j in range(5):
                after = start_table[j]
                dp[i][j] = sum(dp[i-1][v] for v in after)
        return sum(dp[-1]) % (10**9 + 7)

def countVowels(x, n, memo):
    convert = {'a':0, 'e':1, 'i':2, 'o':3, 'u':4}
    x_val = convert[x]
    if n == 1:
        return 1
    if memo[x_val][n] != -1:
        return memo[x_val][n]
    if x == 'a':
        memo[x_val][n] = countVowels('e', n-1, memo)
        return memo[x_val][n]
    elif x == 'u':
        memo[x_val][n] = countVowels('a', n-1, memo)
        return memo[x_val][n]
    elif x == 'e':
        memo[x_val][n] = (countVowels('a', n-1, memo)+countVowels('i', n-1, memo))
        return memo[x_val][n]
    elif x == 'o':
        memo[x_val][n] = (countVowels('i', n-1, memo)+countVowels('u', n-1, memo))
        return memo[x_val][n]
    elif x == 'i':
        memo[x_val][n] = (countVowels('a', n-1, memo)+countVowels('e', n-1, memo)+countVowels('o', n-1, memo)+countVowels('u', n-1, memo))
        return memo[x_val][n]

class Solution:
    def countVowelPermutation(self, n: int) -> int:
        if n == 1:
            return 5
        else:
            memo = [[-1 for j in range(n+1)] for i in range(5)]
            res = countVowels('a', n, memo) + countVowels('e', n, memo) + countVowels('i', n, memo) + countVowels('o', n, memo) + countVowels('u', n, memo)
            return res%1000000007

