class Solution:
    def winnerSquareGame(self, n: int) -> bool:
        if n == 1:
            return True
        num = 0
        dp = [False] * (1 + n)
        while num * num < n:
            dp[num * num] = True
            num += 1
        if num * num == n:
            return True

        for i in range(1, n + 1):
            if dp[i]:
