class Solution:
    def ugly(self, n, a, b, c, ab, ac, bc, abc, num):
        return ((num // a) + (num // b) + (num // c) - (num // ab) - (num // ac) - (num // bc) + (num // abc)) >= n



    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        left = min(a,b,c)
        right = a * b * c * n

        ab = (a*b) // math.gcd(a,b)
        ac = (a*c) // math.gcd(a,c)
        bc = (b*c) // math.gcd(b,c)

        abc = (a * bc) // math.gcd(a,bc)

        while left < right:
            mid = left + (right - left) // 2
            if self.ugly(n, a, b, c, ab, ac, bc, abc, mid):
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        def lcm(a, b):
            return a * b // math.gcd(a, b)

        nums = sorted([a, b, c])
        nums2 = [lcm(a, b), lcm(b, c), lcm(a, c)]
        nums3 = lcm(nums2[0], c)

        lo, hi = n, nums[-1] * n

        while lo < hi:
            mid = (lo + hi) // 2
            rank = (sum(mid // n for n in nums) - sum(mid//n for n in nums2) + mid // nums3)
            if rank < n:
                lo = mid + 1
            else:
                hi = mid
        return lo

