                 count = count + cum_sum_dict[left_sum - k]
             if left_sum in cum_sum_dict:
                 cum_sum_dict[left_sum] = cum_sum_dict[left_sum] + 1
             else:
                 cum_sum_dict[left_sum] = 1

         return count

class Solution:
     def subarraySum(self, nums, k):
         """
         :type nums: List[int]
         :type k: int
         :rtype: int
         """

         dic = {}
         numSum = 0
         dic[0] = 1
         ans = 0
         for i in range(len(nums)):
             numSum += nums[i]
             if (numSum - k) in dic:
                 ans += dic[numSum - k]
             if numSum in dic:
                 dic[numSum] += 1
             else:
                 dic[numSum] = 1
         return ans

class Solution:
     def largestRectangleArea(self, heights):
         """
         :type heights: List[int]
         :rtype: int
         """
         stack = []
         ans = 0
         heights += [-1]
         for i in range(len(heights)):
             left = i
             while 1:
                 if len(stack)==0:
                     stack.append((heights[i], left))
                     break
                 if stack[-1][0]<heights[i]:
                     stack.append((heights[i], left))
                     break
                 elif stack[-1][0]==heights[i]:
                     break
                 else:
                     ans = (i-stack[-1][1])*stack[-1][0] if (i-stack[-1][1])*stack[-1][0]>ans else ans
                     left = stack[-1][1]
                     del stack[-1]
         return ans

