class Solution:
    def largestSumOfAverages(self, A: List[int], K: int) -> float:

        N = len(A)
        P = [0] * (N+1)
        for i in range(1,N+1): 
            P[i] = P[i-1] + A[i-1]

        dp = [(P[N]-P[i])/(N-i) for i in range(N)]
        for k in range(1,K):
            for i in range(K-k-1,N-k):
                dp[i] = max((P[j]-P[i])/(j-i) + dp[j] for j in range(i+1,N-k+1))

        return dp[0]

class Solution:
    def largestSumOfAverages(self, A: List[int], K: int) -> float:
        if not A or len(A) < K:
            return 0
        for i in range(1, len(A)):
            A[i] += A[i-1]

        cache = {}

        def cal(n, k):
            if n <= 0 or k <= 0:
                return 0
            if n < k:
                return 0
            if (n, k) in cache:
                return cache[(n, k)]
            if k == 1:
                cache[(n, 1)] = A[n-1] / n
                return cache[(n, 1)]
            res, cur = 0, 0
            for i in range(n-1, 0, -1):
                res = max(res, (A[n-1] - A[i-1]) / (n-i) + cal(i, k-1))
            cache[(n, k)] = res
            return res

        return cal(len(A), K)

class Solution:
    def new21Game(self, N: int, K: int, W: int) -> float:
        if K==0 or K-1+W<=N:
            return 1
        dp=[1]+[0]*N
        cursum=1
        for i in range(1,N+1):
            # dp[i]=sum(dp[max(0,i-W):min(i,K)])*(1/W)
            dp[i]=cursum*(1/W)
            if i<K:
                cursum+=dp[i]
            if i>=W:
                cursum-=dp[i-W]
        return sum(dp[K:])

class Solution:
    def new21Game(self, N: int, K: int, W: int) -> float:

        if K == 0:
            return 1.0

        if K-1+W <= N:
            return 1.0

        prob = [0.0] * (K+W)
        avg = 0
        for i in range(W):
            prob[K+i] = float(K+i <= N)
            avg += prob[K+i] / W

        for i in range(K)[::-1]:
            prob[i] += avg
            avg += (prob[i] - prob[i+W]) / W

        return prob[0]

class Solution:
    def new21Game(self, N: int, K: int, W: int) -> float:
        if N >= K + W - 1:
            return 1
        if N < K:
            return 0
        if K == 0:
            return 1

        probs = [0]*(W+2)
        probs[0] = 1
        probs[1] = 1/W
        for i in range(1,K):
            probs[(i+1)%(W+2)] = probs[i%(W+2)]*(W+1)/W - probs[(i+2)%(W+2)]/W
        for i in range(W):
            probs[(K+i+1)%(W+2)] = probs[(K+i)%(W+2)] - probs[(K+i+2)%(W+2)]/W

        if K%(W+2) < (N+1)%(W+2):
            return sum(probs[K%(W+2):(N+1)%(W+2)])
        else:
            return sum(probs[K%(W+2):]) + sum(probs[:(N+1)%(W+2)])

class Solution:
    def new21Game(self, N: int, K: int, W: int) -> float:
        if N < K:
            return 0
        if N > K - 1 + W:
            return 1
        dp = [0] * (K + W)
        for k in range(K, N + 1):
            dp[k] = 1

        S = N - K + 1
        for k in range(K - 1, -1, -1):
            dp[k] = S/W
            S += dp[k] - dp[k + W]
        return dp[0]

class Solution():
     def ladderLength(self, beginWord, endWord, wordDict):
         front, back = set([beginWord]), set([endWord])
         wordDict = set(wordDict)
         length = 2
         width = len(beginWord)
         charSet = 'abcdefghijklmnopqrstuvwxyz'

         if endWord not in wordDict:
             return 0

         while front:
             newFront = set()

             for phase in front:
                 for i in range(width):
                     for c in charSet:
                         nw = phase[:i] + c + phase[i+1:]
                         if nw in back:
                             return length
                         if nw in wordDict:
                             newFront.add(nw)
             front = newFront

             if len(front) > len(back):
                 front,back = back,front

             wordDict -= wordDict & front
             length += 1

         return 0

class Solution:
     def ladderLength(self, beginWord, endWord, wordList):
         """
         :type beginWord: str
         :type endWord: str
         :type wordList: List[str]
         :rtype: int
         """
         letters ='abcdefghijklmnopqrstuvwxyz'
         wordList = set(wordList)
         if endWord not in wordList:
             return 0
         reached = set()
         backreached = set()
         reached.add(beginWord)
         backreached.add(endWord)
         wordList.discard(beginWord)
         wordList.discard(endWord)
         depth = 1
         while not (reached & backreached):
             toAdd = set()
             for word in reached:
                 for i,letter in enumerate(word):
                     for newletter in letters:
                         if newletter != letter:
                             newword = word[:i] + newletter + word[i+1:]
                             if newword in backreached:
                                 return depth + 1
                             elif newword in wordList:
                                 toAdd.add(newword)
                                 wordList.remove(newword)
             if len(toAdd) == 0:
                 return 0
             else:
                 depth += 1
                 reached = toAdd
                 if len(reached) > len(backreached):
                     reached, backreached = backreached, reached
         return depth

class Solution:
     def ladderLength(self, beginWord, endWord, wordList):
         """
         :type beginWord: str
         :type endWord: str
         :type wordList: List[str]
         :rtype: int
         """             

         words = set(wordList)
         if endWord not in words:
             return 0

         beginQ, endQ = {beginWord}, {endWord}
         dist = 2
         while beginQ:
             print(('beginQ', beginQ, 'endQ', endQ))
             newq = set()
             for u in beginQ:
                 for i in range(len(u)):
                     for c in 'abcdefghijklmnopqrstuvwxyz':
                         v = u[:i] + c + u[i+1:]
                         if v in words:
                             if v in endQ:
                                 return dist
                             newq.add(v)

             dist += 1            
             beginQ = newq
             if len(beginQ) > len(endQ):
                 beginQ, endQ = endQ, beginQ

             words -= beginQ

         return 0

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:

        total = sum(arr)
        if total <= target:
            return max(arr)

        arr = sorted(arr)

        min_num = target // len(arr)
        if min_num <= arr[0]:
            below = len(arr) * min_num
            above = len(arr) * (min_num + 1)

            if abs(target - below) <= abs(target - above):
                return min_num
            else:
                return min_num + 1
        return self.findBestValue(arr[1:], target - arr[0])

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        # 
        if not arr:
            return 0
        if len(arr) == 1:
            return arr[0] if arr[0] <= target else target
        value = 1
        sum_up = 0
        index = 0
        last_sum = 0
        arr.sort()
        while value < arr[-1]:

            current_sum = 0
            while value >= arr[index]:
                sum_up += arr[index]
                index += 1
            current_sum =  sum_up + ((len(arr) - index) * value)
            if current_sum == target:
                return value
            elif current_sum > target:
                if abs(last_sum - target) <= abs(current_sum - target):
                    return value - 1
                else:
                    return value
            else:
                last_sum = current_sum
            value += 1            

        return value

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        arr.sort()
        n = len(arr)
        for i in range(n):
            sol = round(target / n)
            if arr[i] >= sol:
                return sol
            target -= arr[i]
            n -= 1
        return arr[-1]

