        for i in range(1, len(arrThree)):
            if arrThree[i - 1] > 0: 
                arrThree[i] +=arrThree[i - 1]

        arrDiff = max(arrThree) - max(arrTwo)


        return (max(arrTwo) + (k-2)*arrDiff) % (10**9 + 7)






