class Solution:
    def getWinner(self, arr: List[int], k: int) -> int:
        arrLen = len(arr)
        if(arrLen <= k):
            arr.sort()
            return arr[-1]

        targ = 0
        i1 = 0
        i2 = 1

        while(targ < k) and arrLen > i2:
            if(arr[i1] > arr[i2]):
                i2 += 1
            else:
                i1 = i2
                i2 += 1
                targ = 0

            targ += 1

        return arr[i1]
class Solution:
    def getWinner(self, arr: List[int], k: int) -> int:       

        if len(arr)<k:
            return max(arr) 

        if k==1:
            return max(arr[0],arr[1])

        cnt=0
        while cnt<k:
            j=1
            while arr[0]>arr[j]:
                cnt+=1
                j+=1
                if cnt==k:
                    return arr[0]
            arr.append(arr[0])
            arr.pop(0)
            cnt=1

