class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        def dp(mp, cp, turn):
            if turn>=N: return 0
            if mp==0: return 1
            if mp==cp: return 2

            if (mp, cp, turn) in memo: return memo[(mp, cp, turn)]

            res = 0
            if turn%2==0:
                if any(dp(nxt, cp, turn+1)==1 for nxt in graph[mp]):
                    res = 1
                elif all(dp(nxt, cp, turn+1)==2 for nxt in graph[mp]):
                    res = 2
            else:
                if any(dp(mp, nxt, turn+1)==2 for nxt in graph[cp] if nxt!=0):
                    res = 2
                elif all(dp(mp, nxt, turn+1)==1 for nxt in graph[cp] if nxt!=0):
                    res = 1

            memo[(mp, cp, turn)] = res
            return res

        N = len(graph)
        memo = {}
        return dp(1, 2, 0)
class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        n = 0
        for i in range(len(graph)):
            for j in range(len(graph[i])):
                n = max(n, graph[i][j])

        status = [[[0] * 3 for i in range(n + 1)] for j in range(n + 1)] # s[m][c][t]

        queue = []
        for i in range(1, n + 1):
            status[i][i][1] = 2
            status[i][i][2] = 2
            status[0][i][1] = 1
            status[0][i][2] = 1
            queue.append((i, i, 1))
            queue.append((i, i, 2))
            queue.append((0, i, 1))
            queue.append((0, i, 2))

        while queue:
            next_queue = []
            for element in queue:
                mouse = element[0]
                cat = element[1]
                turn = element[2]
                if turn == 1:
                    for cat_pre in graph[cat]:
                        if cat_pre == 0:
                            continue
                        if status[mouse][cat_pre][2] == 0:
                            status[mouse][cat_pre][2] = 1
                            for cat_alt in graph[cat_pre]:
                                if cat_alt == 0:
                                    continue
                                if status[mouse][cat_alt][1] == 2:
                                    status[mouse][cat_pre][2] = 2
                                    break
                                elif status[mouse][cat_alt][1] == 0:
                                    status[mouse][cat_pre][2] = 0
                            if status[mouse][cat_pre][2] > 0:
                                next_queue.append((mouse, cat_pre, 2))
                else:
                    for mouse_pre in graph[mouse]:
                        if status[mouse_pre][cat][1] == 0:
                            status[mouse_pre][cat][1] = 2
                            for mouse_alt in graph[mouse_pre]:
                                if status[mouse_alt][cat][2] == 1:
                                    status[mouse_pre][cat][1] = 1
                                    break
                                elif status[mouse_alt][cat][2] == 0:
                                    status[mouse_pre][cat][1] = 0
                            if status[mouse_pre][cat][1] > 0:
                                next_queue.append((mouse_pre, cat, 1))
            queue = next_queue

        return status[1][2][1]









class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        n = len(graph)
        cache = [[[-1] * (2 * n) for _ in range(n)] for _ in range(n)]
        def move(cat, mouse, t):
            if t == 2 * n:
                return 0
            elif mouse == 0:
                return 1
            elif cat == mouse:
                return 2
            if cache[cat][mouse][t] == -1:
                mouse_move = (t % 2) == 0
                if mouse_move:
                    best_result = 2
                    for pos in graph[mouse]:
                        result = move(cat, pos, t + 1)
                        if result == 1:
                            cache[cat][mouse][t] = 1
                            return 1
                        if result == 0:
                            best_result = 0
                else:
                    best_result = 1
                    for pos in graph[cat]:
                        if pos == 0:
                            continue
                        result = move(pos, mouse, t + 1)
                        if result == 2:
                            cache[cat][mouse][t] = 2
                            return 2
                        if result == 0:
                            best_result = 0
                cache[cat][mouse][t] = best_result
            return cache[cat][mouse][t]
        return move(2, 1, 0)

