class Solution:
    def distinctSubseqII(self, S: str) -> int:
        res, last = 1, {}
        for c in S:
            temp = res * 2
            if c in last:
                temp -= last[c]
            last[c] = res
            res = temp
        return (res - 1) % (10**9 + 7)
class Solution:
    def distinctSubseqII(self, s: str) -> int:
        n = len(s)
        MOD = 10**9 + 7
        seen = dict()

        a = 1
        for i in range(n):
            char = s[i]
            b = 2 * a
            if char in seen:
                b -= seen[char]

            b %= MOD
            seen[char] = a
            a = b
        return a - 1

