class Solution:
    def distinctSubseqII(self, S: str) -> int:

        # DP(i) = number of distinct subseq ending at i
        # DP(i) = 1 + sum(DP[:i]) if it is a new letter
        # DP(i) = 1 + sum(DP[j:i]) where j is last occurence of letter S[i]

        # abc -> [1, 2, 4]
        # aba -> [1, 2, 3]
        # aaa -> [1, 1, 1]
        # abaa -> [1, 2, 3, 3] a, b, ab, aa, ba, aba, aaa, baa, abaaa

        n = len(S)
        MOD = int(1e9 + 7)
        I = dict()
        PS = [0] * (n + 1)

        for i, c in enumerate(S):
            if c not in I:
                dpi = 1 + PS[i] % MOD
            else:
                dpi = PS[i] - PS[I[c]]
            I[c] = i
            PS[i + 1] = PS[i] + dpi

        return PS[-1] % MOD

class Solution:
    def distinctSubseqII(self, S: str) -> int:
        def itertools_appr():
            if not S: return 0
            from itertools import combinations
            n = len(S)
            MOD = 1000_000_000 + 7
            l = 0
            for i in range(1,n+1):
                l += len(set(combinations(S, i))) % MOD
            return l

        def from_soln():
            '''
            Imagine we knew the subsequence count without the last char, dp[-1]
            dp[-1] should be twice of the previous one. However we need to account
            for the presence of the same last char previously.
            S = \"abab\"
            dp[0], with chars upto S[0] = { '', 'a' }
            dp[1], with chars upto S[1] = dp[1] * 2 - subseqs we would have
                double counted. {'', 'a', 'b', 'ab'}
                = 4
            dp[2], with chars upto S[2] = 2*dp[1] - adj for double counting
                {'', 'a', 'b', 'ab'} --> dp[1]
                {'a', 'aa', 'ba', 'aba'} --> dp[1] + 'a'
                'a' is double counted = dp[last['a']] - 1
                = 7
            dp[3], with chars upto S[3] = 2*dp[2] - adjustments for double counting
                {'','a','b','ab','aa','ba','aba'} <-- dp[2]
                {'b','ab','bb','abb','aab','bab','abab'} <-- dp[2] + 'b'
                'b', 'ab' are double counted = dp[last['b']] - 1
                = 14

            dp[k] = 2*dp[k-1] - dp[last[S[k]]] - 1, (1 for '')
            '''
            dp = [1]
            last = {}
            for i,x in enumerate(S):
                dp.append(2*dp[-1])
                if x in last:
                    dp[-1] -= dp[last[x]]
                last[x] = i
            return (dp[-1] - 1) % (10**9+7)
        return from_soln()

class Solution:
    def sumSubarrayMins(self, A: List[int]) -> int:
        result = 0
        tempDq = []
        A = [0] + A + [0]
        for idx in range(len(A)):
            while tempDq and A[tempDq[-1]] > A[idx]:
                prevIdx = tempDq.pop()
                lastIdx = tempDq[-1]
                result += A[prevIdx] * (prevIdx - lastIdx) * (idx - prevIdx)
            tempDq.append(idx)
        return result % (10 ** 9 + 7)

class Solution:
    def sumSubarrayMins(self, A: List[int]) -> int:
        stack = []
        result = 0
        A = [0] + A + [0]

        for i, x in enumerate(A):
            while stack and x < A[stack[-1]]:
                j = stack.pop()
                result += A[j] * (i - j) * (j - stack[-1])
            stack.append(i)

        return result % (10**9 + 7)

class Solution:
    def isPossibleDivide(self, s: List[int], k: int) -> bool:
        if len(s) % k != 0:
            return False

        ctr = collections.Counter(s)

        for _ in range(len(s) // k):
            mn = []
            for i in ctr:
                if mn == [] and ctr[i] > 0:
                    mn = [i]
                elif ctr[i] > 0:
                    if i < mn[0]:
                        mn = [i]

            for i in range(k):
                ctr[mn[0] + i] -= 1
                if ctr[mn[0] + i] < 0:
                    return False

        return True

