    swaps = 0
    for i in range(len(grid[0])):
      if grid_ints[i] > bar:
        j = i
        while grid_ints[j] > bar:
          j += 1
          if j >= len(grid[0]):
            return -1
        while j > i:
          grid_ints[j], grid_ints[j-1] = grid_ints[j-1], grid_ints[j]
          swaps += 1
          j -= 1
      bar = (bar << 1) + 1

    return swaps

