class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        # self.res = sys.maxsize
        ht = {}
        res = self.dfs(jobDifficulty, d, ht)
        if res == sys.maxsize:
            return -1
        return res

    def dfs(self, nums, K, ht):
        if K == 1:
            if len(nums) == 0:
                return sys.maxsize
            return max(nums)
        key = (len(nums), K)
        if key in ht:
            return ht[key]
        res = sys.maxsize
        a = 0
        for i in range(len(nums)):
            a = max(a, nums[i])
            b = self.dfs(nums[i+1:], K-1, ht)
            if a + b < res:
                res = a + b
        ht[key] = res
        return res
class Solution:
    def minDifficulty(self, jD: List[int], d: int) -> int:
        if len(jD) < d: return -1
        memo = {}
        def dp(memo, jD, i, d): # 求解mD(jD[i:], d)
            if len(jD) - i  < d: return -1
            if d == 1: return max(jD[i:])
            if (i, d) in memo:
                return memo[(i, d)]
            ans, cur = 9999999999, 0
            for j in range(i, len(jD)): #遍历S(D_1)
                cur = max(cur, jD[j])
                x = dp(memo, jD, j + 1, d - 1)#核心代码 md(D_1^{rest}, d-1)
                if x != -1: 
                    ans = min(ans, cur + x)
            memo[(i, d)] = ans
            return ans
        return dp(memo, jD, 0, d)
class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        if len(jobDifficulty) < d:
            return -1

        self.cache = {}
        return self.helper(jobDifficulty, d, 0)

    def helper(self, jobDifficulty: List[int], d: int, start: int) -> int:
        if d == 1:
            return max(jobDifficulty[start:])

        if (d, start) not in self.cache:
            self.cache[(d, start)] = min(
                [
                    max(jobDifficulty[start:end]) + self.helper(jobDifficulty, d-1, end) 
                    for end in range(start+1, len(jobDifficulty)-d+2)
                ]
            )

        return self.cache[(d, start)]
