        visited[0] = True
        numCoins = 1
        nextStart = []
        while start:
            for v in start:
                for coin in coins:
                    nextVal = v + coin
                    if nextVal > amount or visited[nextVal]:
                        continue
                    elif nextVal == amount:
                        return numCoins
                    else:
