class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:

        if n == 1:
            return 0

        # need data structure to keep track of individual employees
        time = collections.defaultdict(int)

        # do some preprocessing
        # create a map worksUnder
        # id -> {ids of employees that work under this manager}
        worksUnder = collections.defaultdict(set)

        for i in range(n):
            # employee i works under manager[i]
            worksUnder[manager[i]].add(i)

        stack = [headID]
        while stack:
            managerID = stack.pop()
            for i in worksUnder[managerID]:
                    # employee i works under managerID
                    # emplyee i's time is his manager's time plus 
                    # his manager's inform time
                    time[i] = informTime[managerID] + time[managerID]
                    stack.append(i)

        return max(time.values())
class Employee:
    def __init__(self, employeeID, informTime):
        self.id = employeeID
        self.informTime = informTime 
        self.sub = []

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        if n == 1:
            return informTime[0]

        head = self.buildEmpTree(n, manager, headID, informTime)

        return self.maxTime(head)

    def buildEmpTree(self, n, manager, headID, informTime):
        s = {}
        for i in range(n):
            s[i] = Employee(i, informTime[i])

        for i in range(n):
            if manager[i] == -1:
                continue
            s[manager[i]].sub.append(s[i])

        return s[headID]

    def maxTime(self, root):
        if not root.sub:
            return root.informTime

        curMax = root.informTime

        for subordinate in root.sub:
            curMax = max(curMax, root.informTime + self.maxTime(subordinate))

        return curMax
class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        if n <= 1:
            return 0
        sub = collections.defaultdict(list)
        for i in range(len(manager)):
            sub[manager[i]].append(i)

        total = 0
        q = collections.deque([(headID, 0)]) #id, time
        while q:
            employee, time = q.popleft()
            if not sub[employee]:
                total = max(total, time)
            for nxt in sub[employee]:
                q.append((nxt, time+informTime[employee]))
        return total
