class Solution:
    def maxValueAfterReverse(self, nums: List[int]) -> int:
        ans = 0
        for i in range(len(nums)-1):
            ans += abs(nums[i+1]-nums[i])

        d = 0
        for i in range(1,len(nums)-1):
            d = max(d, abs(nums[0]-nums[i+1]) - abs(nums[i]-nums[i+1]),
                       abs(nums[-1]-nums[i-1]) - abs(nums[i]-nums[i-1]))
        high = -sys.maxsize
        low = sys.maxsize
        for x, y in zip(nums, nums[1:]):
            high = max(high, min(x, y))
            low = min(low, max(x, y))
        return ans + max(d, (high-low)*2)

class Solution:
    def maxValueAfterReverse(self, nums: List[int]) -> int:
        # 三种情况，从头到中间某个地方进行reverse；
        # 从中间到最后进行reverse，中间的某一段进行reverse
        total, res, min2, max2 = 0, 0, float('inf'), float('-inf')
        for a, b in zip(nums[:-1], nums[1:]):
            total += abs(a - b)
            res = max(res, abs(nums[0] - b) - abs(a - b))
            res = max(res, abs(nums[-1] - a) - abs(a - b))
            min2, max2 = min(min2, max(a, b)), max(max2, min(a, b))
        return total + max(res, (max2 - min2) * 2)

