class Solution:
    def find_factors(self, n):
        factors = []
        i = 1
        j = n
        while True:
            if i*j == n:
                factors.append(i)
                if i == j:
                    break
                factors.append(j)
            i += 1
            j = n // i
            if i > j:
                break
        return factors
    def sumFourDivisors(self, nums: List[int]) -> int:
        d = 0
        for i in nums:
            f = self.find_factors(i)
            if len(f)==4:
                d+=f[0]+f[1]+f[2]+f[3]
        return d
class Solution:
    def sumFourDivisors(self, nums: List[int]) -> int:
        # p1 * p2
        # 1, p1, p2, p1 * p2
        # p^n: n+1
        # 8: 1, 2, 4, 8
        # p^3

        def find_divisors(n):
            i = 1
            divisors = []
            while i * i < n:
                if n % i == 0:
                    divisors.append(i)
                    divisors.append(n // i)
                i += 1
            if i * i == n:
                divisors.append(i)
            return divisors

        ans = 0
        for n in nums:
            divisors = find_divisors(n)
            if len(divisors) == 4:
                ans += sum(divisors)
        return ans
