class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        indegree = [0 for i in range(n)]
        # Count in-degree
        for i in range(len(leftChild)):
            if leftChild[i] != -1:
                indegree[leftChild[i]] += 1
                if indegree[leftChild[i]] > 1:
                    return False
            if rightChild[i] != -1:
                indegree[rightChild[i]] += 1
                if indegree[rightChild[i]] > 1:
                    return False
        # Find potential root
        root = -1
        for node in range(len(indegree)):
            if indegree[node] == 0:
                if root == -1:
                    root = node
                else:
                    return False
        if root == -1:
            return False

        # Exactly n nodes in single tree
        def countNodes(root, l, r):
            if root is -1:
                return 0
            return 1 + countNodes(l[root], l, r) + countNodes(r[root], l, r)
        return countNodes(root, leftChild, rightChild) == n

class Solution:
    def validateBinaryTreeNodes(self, n, left, right):
        roots={*range(n)}
        for x in left+right:
            if x==-1:
                continue
            if x not in roots:
                return False
            roots.discard(x)
        if len(roots)!=1:
            return False
        k=0
        stk=[roots.pop()]
        while stk:
            node=stk.pop()
            k+=1
            l,r=left[node],right[node]
            if l!=-1:
                stk.append(l)
            if r!=-1:
                stk.append(r)
        return k==n

class Solution:   # 2020-10-09-7
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        # rules: (1) descendants cannot point to ancestors (i.e. no cycles)
        # (2) a node cannot be pointed to more than once (partly overlaps with rule 1)
        # (3) the tree should be connected, i.e. not a forest

        vis = set()
        heads = set()

        def dfs(i):
            if i == -1:
                return True
            vis.add(i)
            for child in [leftChild[i], rightChild[i]]:
                if child in vis:
                    if child not in heads:
                        return False
                    else:
                        heads.remove(child)
                else:
                    if not dfs(child):
                        return False
            return True

        for i in range(n):
            if i not in vis:
                if not dfs(i):
                    return False
                heads.add(i)

        return len(heads) == 1

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        parents = [-1] * n
        for p in range(n):
            if leftChild[p] != -1:
                if parents[leftChild[p]] != -1:
                    return False
                parents[leftChild[p]] = p
            if rightChild[p] != -1:
                if parents[rightChild[p]] != -1:
                    return False
                parents[rightChild[p]] = p

        found = False
        for p in parents:
            if p == -1:
                if found:
                    return False
                found = True  

        visit = [0] * n

        def dfs(ix):
            if ix == -1:
                return True
            if visit[ix] == 1:
                return False
            visit[ix] = 1
            if not dfs(parents[ix]):
                return False
            visit[ix] = 2
            return True

        for i in range(n):
            if visit[i] == 2:
                continue
            if not dfs(i):
                return False
        return True

