def touchAnyNodes(visited,graph,infected) -> (bool,int):
    newVisited = visited.copy()
    for node in visited:
        for idx in range(len(graph[node])):
            if graph[node][idx] == 1 and (not idx in visited) and (not idx in newVisited):
                if idx in infected:
                    return True,0
                newVisited.append(idx)
    if len(newVisited) == len(visited):
        return False,len(visited)
    return touchAnyNodes(newVisited,graph,infected)
class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        initial.sort()
        visited = []
        result = [-1, 0]  # index,count

        for i in range(len(graph)):
            if i in visited:
                continue
            else:
                temp = [-1, 0]
                stack = [i]
                visited.append(i)
                stack_num = 1;
                while stack:
                    index = stack.pop(0)
                    if index in initial:
                        if temp[0] == -1:
                            temp[0] = index
                        temp[1] += 1
                    for j in range(len(graph[index])):
                        if graph[index][j] == 1 and (j not in visited):
                            stack.append(j)
                            stack_num += 1
                            visited.append(j)
                if temp[1] == 1:
                    if result[1] < stack_num:
                        result[0] = temp[0]
                        result[1] = stack_num
        return result[0] if result[0] != -1 else initial[0]

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        #dfs to find all node in a subgraph, only subgraph with 1 infected node can be saved as we can remove only one node
        init = set(initial)
        total_visited = set()
        res, max_subgraph_len = min(initial), 0
        for node in range(len(graph)):
            if node not in total_visited:
                visited = set([node])
                self.dfsConnected(graph, node, visited)
                #find infected node in subgraph
                infected = visited & init
                if len(infected) == 1:
                    if len(visited) > max_subgraph_len or (len(visited) == max_subgraph_len and min(infected) < res):
                        res, max_subgraph_len = min(infected), len(visited)
                total_visited |= visited
        return res

    def dfsConnected(self, graph, node, visited):
        for neighbor in range(len(graph[node])):
            if graph[node][neighbor] == 1 and neighbor not in visited:
                visited.add(neighbor)
                self.dfsConnected(graph, neighbor, visited)

