    cc[y][x] = cc[y][x - 1] + cc[y - 1][x] - cc[y - 1][x - 1]
    if (y + x) % 2 == 0:
        cc[y][x] += int(ci[y - 1][x - 1] != '1')
    else:
        cc[y][x] += int(ci[y - 1][x - 1] != '0')

def cache_creation(m,n):
    for y in range(1,n+1):
        for x in range(1, m + 1):
            cache_creation_part(x,y)

