def treeProduct(num, h, root, ch):
 if ch >= h:
  return num[root]

 left = (root * 2) + 1
 right = (root * 2) + 2

 ret1 = treeProduct(num, h, left, ch + 1)
 ret2 = treeProduct(num, h, right, ch + 1)

 return num[root] * max(ret1, ret2)

