def chef_cost(A,B,n):
 checksum=0
 mn1=min(A)
 mn2=min(B)
 mn=min(mn1,mn2)
 mpa={}
 for i in range(n):
  checksum^=A[i]
  if A[i] not in mpa:
   mpa[A[i]]=1
  else:
   mpa[A[i]]+=1 
 mpb={}
 for i in range(n):
  checksum^=B[i]
  if B[i] not in mpb:
   mpb[B[i]]=1
  else:
   mpb[B[i]]+=1
 if checksum:
  return -1
 for i in mpa: 
  if i in mpb:
   dx=min(mpa[i],mpb[i])
   mpa[i]-=dx
   mpb[i]-=dx
 a1=[]
 b1=[]
 for i in mpa:
  for j in range(mpa[i]//2):
   a1.append(i)
 for i in mpb:
  for j in range(mpb[i]//2):
   b1.append(i)
 a1.sort()
 b1.sort(reverse=True)
 cost = 0
 for i in range(len(a1)):
  cost += min(2*mn,min(a1[i],b1[i]))
 return cost

