    r = n;
    while l + 1 < r:
        mid = l  + ((r-l) >> 1);
        if max_edges(n,mid) < mid:
            r = mid - 1;
        else:
            l = mid;
    if max_edges(n,r) >= r:
        return find_edges(n,r);
