def recur(arr,k):
 if len(arr) == k:
  return sum(arr)
 ans = float('inf')
 for i in range(len(arr)-1):
  for j in range(i+1, len(arr)):
   temp = arr[:]
   temp.remove(arr[i])
   temp.remove(arr[j])
   temp.append(arr[i]*arr[j])
   ans = min(ans, recur(temp,k))
 return ans

