def primeFactors(n):
 d = {}
 while n % 2 == 0:
  n = n // 2
  if 2 in d:
   d[2] += 1 
  else:
   d[2] = 1 
 for i in range(3,int(math.sqrt(n))+1,2):
  while n % i== 0:
   if i in d:
    d[i] += 1 
   else:
    d[i] = 1 
   n = n // i
 if n > 2:
  if n in d:
   d[n] += 1 
  else:
   d[n] = 1

 return d

