def is_zigzag(h):
 if (len(h) <= 1):
  return True
 sign = h[1] - h[0]
 if (len(h) == 2 and sign == 0):
  return False
 for i in range(2, len(h)):
  diff = h[i] - h[i - 1]
  if (diff * sign >= 0):
   return False
  sign = diff 
 return True

def is_possible(h, r):
 for i in range(1, len(h)):
  diff = h[i] - h[i - 1]
  if (diff < 0 and r[i] > r[i - 1]):
   return True
  elif (diff > 0 and r[i] < r[i - 1]):
   return True
  elif (diff == 0 and r[i] != r[i - 1]):
   return True
 return False

