def gcd(m,n):
 if m > n :
  (a,b) = (n,m)
 else:
  (a,b) = (m,n)
 r = b
 while r > 1:
  r = b%a 
  (a,b) = (r,a)
 if r == 0:
  return b
 else:
  return 1

def rlmaker(rl,pc,n):
