        graph = defaultdict(list)
        for e in self.edges:
            u = e[0]
            v = e[1]
            w = e[2]
            graph[u].append([v,w])
            graph[v].append([u,w])
        return graph

    def precompute(self):
        self.maxiedges = [0]*6
        self.B = [[0 for i in range(101)] for i in range(101)]
