import math 
def no_of_factors(n) : 
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1) : 
        if (n % i == 0) : 
            if (n / i == i) : 
                count = count + 1
            else :
                count = count + 2

    return count 

