class Container:
    def __init__(self):
        self.comp = [0, 0]
        self.state = -1
    def process(self):
        if self.state == -1 or self.state == 1:
            if self.comp == [1, 1]:
                self.state = 3
            else:
                self.state = 0
            self.comp[0] += 1
        elif self.state == 0 or self.state == 3:
            self.state = 1
            self.comp[1] += 1


