def twonocheck(k, j, r, c):
 if k % r == 0:
  nc = c - k / r
  if r * nc == j:
   return True
 if k % c == 0:
  nr = r - k / c
  if nr * c == j:
   return True
 return False


def nocheck(m, k, j, r, c):
 if m % r == 0:
  nc = c - m / r
  if nc != 0:
   if twonocheck(k, j, r, nc):
     return True
   elif twonocheck(j, k, r, nc):
    return True
 if m % c == 0:
  nr = r - m / c
  if nr != 0:
   if twonocheck(k, j, nr, c):
    return True
   elif twonocheck(j, k, nr, c):
    return True
 return False

