   idx,char = stack[len(stack)-1]
   if((idx%2 and s[i]=='B') or (i%2 and char=='B')):
    bans += abs(i-idx)**c
   elif((idx%2 and s[i]=='G') or (i%2 and char=='G')):
    gans += abs(i-idx)**c
   stack.pop(len(stack)-1)
  else:
   stack.append((i,s[i]))

 if(gcount==bcount):
  return min(bans,gans)
 elif(gcount>bcount):
  return bans
 return gans
