def sub_determinant(matrix, i):
    sub_matrix = []
    for j in range(1,len(matrix)):
        sub_matrix.append(matrix[j][:i] + matrix[j][i+1:])
    return sub_matrix

def determinant(matrix):
    if len(matrix) == 0:
        return 0
    elif len(matrix) == 1:
        return matrix[0][0]
    elif len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1]*matrix[1][0]
    else:
        sum = 0
        for i in range(0,len(matrix)):
            if 1 == i & 1:
                sum = sum - matrix[0][i] * determinant(sub_determinant(matrix,i))
            else:
                sum = sum + matrix[0][i] * determinant(sub_determinant(matrix,i))
        return sum

def determinant(m):
    if len(m) == 1 : return m[0][0]
    if len(m) == 2 : return (m[0][0]*m[1][1]) - (m[0][1]*m[1][0])
    li = [[m[j][:i] + m[j][i+1:] for j in range(1,len(m))] for i in range(len(m))]
    return sum(-m[0][i]*(determinant(j)) if i&1 else m[0][i]*(determinant(j)) for i,j in enumerate(li))

def determinant(m):
    a = 0
    if len(m) == 1:
        a = m[0][0]
    else:
        for n in xrange(len(m)):
            if (n + 1) % 2 == 0:
                a -= m[0][n] * determinant([o[:n] + o[n+1:] for o in m[1:]])
            else:
                a += m[0][n] * determinant([o[:n] + o[n+1:] for o in m[1:]])

    return a

