def H(Q) :
  M = functrion_L(Q)
  R = [9E9,0]
  def H(V,S = set(),C = 0) :
    if V in S :
      R[:] = min(R[0],C),max(R[1],C)
      return 9
    S.add(V)
    T = 0
    for B in M[V] : T = H(B,S,-~C) or T
