def is_prime(n):
    if n<2:
        return False
    elif n==2:
        return True
    elif n%2==0:
        return False
    for i in range(3,int(n**0.5)+1,2):
        if n%i==0:
            return False
    return True

memo={}

def _prot_part(arr):
    if len(arr)<2:
        return set({(arr[0],)})
    elif len(arr)==2:
        return set([tuple(sorted(arr)),(arr[0]*arr[1],)])
    elif tuple(arr) in memo:
        return memo[tuple(arr)]
    r=set()
    for j in range(1,len(arr)//2+1):
        for t in combinations(arr,j):
            arr2=arr[:]
            for e in t:
                arr2.remove(e)
            s2=_prot_part(arr2)
            for e1 in _prot_part(list(t)):
                for e2 in s2:
                    r.add(tuple(sorted(list(e1+e2))))
    r.add((reduce(mul,arr),))
    memo[tuple(arr)]=r
    return r

