        r.append(2)
        n//=2
    x=3
    while(n>1 and not is_prime(n)):
        while(n%x==0):
            r.append(x)
            n//=x
        x+=2
    if n>1:
        r.append(n)
    p=_prot_part(r)
    if com=='max':
