           for i in range(len(COLUMNS) - 3) for j in range(len(ROWS))] \
        + [{(COLUMNS[i], ROWS[j+k]) for k in range(4)}
           for i in range(len(COLUMNS)) for j in range(len(ROWS) - 3)] \
        + [{(COLUMNS[i+k], ROWS[j+k]) for k in range(4)}
           for i in range(len(COLUMNS) - 3) for j in range(len(ROWS) - 3)] \
        + [{(COLUMNS[i+k], ROWS[j-k]) for k in range(4)}
           for i in range(len(COLUMNS) - 3) for j in range(3, len(ROWS))]

def who_is_winner(pieces_positions):
    players = {}
    board = dict.fromkeys(COLUMNS, 0)
    for position in pieces_positions:
        column, player = position.split('_')
        pos = (column, board[column])
        board[column] += 1
        players.setdefault(player, set()).add(pos)
        if any(line <= players[player] for line in LINES):
            return player
    return "Draw"

def who_is_winner(moves):
    G = {(c, r):' ' for r in range(6) for c in range(7)}

    for col, colour in [(ord(m[0]) - ord('A'), m[2]) for m in moves]:
        for row in range(6):
            if G[(col, row)] == ' ':
                G[(col,row)] = colour
                break
        if colour*4 in ' '.join([''.join(G[(col, k)] for k in range(6)),
                                 ''.join(G[(k, row)] for k in range(7)),
                                 ''.join(G.get((k, row - col + k), ' ') for k in range(7)),
                                 ''.join(G.get((k, row + col - k), ' ') for k in range(7))]): return {'Y':'Yellow', 'R':'Red'}[colour]
    return 'Draw'

from itertools import count, takewhile

X, Y, HALF_DIRS = 6, 7, ((0,1),(1,0),(1,1),(1,-1))


def who_is_winner(lstMoves):

    def isWinner(): return any(countAligned(*dirs)>=4 for dirs in HALF_DIRS)

    def isInsideAndSameGuy(a,b): return 0<=a<X and 0<=b<Y and board[a][b]==who

    def countAligned(dx,dy):
        return 1 + sum( sum( takewhile(bool, (isInsideAndSameGuy(x+dx*swap*n, y+dy*swap*n) for n in count(1)) ))
                        for swap in (1,-1) )


    board = [[' ']*Y for _ in range(X)]
    xIdx  = [0]*Y

    for move in lstMoves:
        y, who      = ord(move[0])-65, move[2]
        x           = xIdx[y]
        board[x][y] = who
        xIdx[y]    += 1
        if isWinner(): return move[2:]
    else:
