def parse_monom(monom):
    if 'x' not in monom: monom = monom + 'x^0'
    if monom.startswith('x'): monom = '1' + monom
    if monom.startswith('-x'): monom = '-1' + monom[1:]
    if monom.endswith('x'): monom = monom + '^1'
    coefficient, degree = map(int, monom.replace('x', '').split('^'))
    return degree, coefficient

def differentiate(equation, point):
    monoms = equation.replace('-', '+-').lstrip('+').split('+')
    polynom = dict(map(parse_monom, monoms))
    return sum(coefficient * degree * point ** (degree - 1)
               for degree, coefficient in polynom.items() if degree)

def differentiate(equation, point):

    if equation[0] != '-': equation = '+' + equation

    equation = equation.replace('+x', '+1x').replace('-x', '-1x').replace('+', ' ').replace('-', ' -')

    terms = [[int(e) for e in (w + '^1' if '^' not in w else w).split('x^')] for w in equation.split() if 'x' in w]

    return sum(c * p * point ** (p - 1) for c, p in terms)

def differentiate(equation, point):
    #This can almost certainly be done waaaaay better with regex ...

    #Where are all the signs between terms?
    signs = [i for i in range(len(equation)) if equation[i] in "+-"]
    if not 0 in signs: signs = [0] + signs

    #Parse the coefficients and powers (all assumed integers)
    coeffs = []
    powers = []
    for i in range(len(signs)):
        if i+1 == len(signs):
            term = equation[signs[i]:]
        else:
            term = equation[signs[i]:signs[i+1]]
        if "^" in term:
            i = term.index("^")
            powers += [int(term.split("^")[1])]
        elif "x" in term:
            powers += [1]
        if "x" in term:
            c = term.split("x")[0]
            if c in ["","+","-"]:
                coeffs += [-1 if c == "-" else 1]
            else:
                coeffs += [int(c)]
    return sum([c*p*point**(p-1) for c,p in zip(coeffs,powers)])

