        triangle = mid * prefix + mid * (d + mid * d) // 2
        prevTriangle = (mid-1) * prefix + (mid-1) * (d + (mid-1) * d) // 2
        nextTriangle = (mid+1) * prefix + (mid+1) * (d + (mid+1) * d) // 2
        if triangle >= n:
            if prevTriangle < n:
                return prevTriangle
            else:
                r = mid - 1
        else:
            if nextTriangle >= n:
                return triangle
            else:
                l = mid


    return l * prefix + l * (d + l * d) // 2

