def unique_prime_factors(n): # Generate only one instance of each prime factor, save time ^_^
    i = 2
    factors = set()
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.add(i)
    if n > 1:
        factors.add(n)
    return factors

def proper_fractions(n):
    if n == 1:
        return 0
    output = n
    for p in unique_prime_factors(n): # We can now use Euler's totient function to solve directly!
        output //= p
        output *= (p-1)
    return output

def proper_fractions(n):
    #find all prime factors (without repetitions) of n
    factors=set()
    i=2
    input=n
    while i*i<=input:
        if input%i==0:
            factors.add(i)
            input=input//i
        else:
            i=i+1
    factors.add(input)
    #use Euler totient formula to find the amount of numbers coprime to n that are smaller than n
    result=n
    for j in factors:
        result=result*(1-(1/j))
    return int(result)

def euler(n):
    res = 1.0*n
    p = 2
    while p*p <= n:
        if n%p == 0:
            while n%p == 0:
                n = n/p
            res *= (1.0 - (1.0/p) )
        p += 1

    if n > 1:
        res *= (1.0 - (1.0/n) )

    return int(res)

