@lru_cache(maxsize=None)
def calc(d, k, is_first_digit=True):
    if d < 0 or k < 0 or d < k:
        return 0
    elif d == k:
        return 9 ** k
    return calc(d - 1, k - 1, False) * 9 + calc(d - 1, k, False) * (not is_first_digit)


