    ans = sum(calc(d, k) for d in range(k, len(str(n))))
    for d in range(1, int(str(n)[0])):
        ans += calc(len(str(n))-1, k-1, False)
    return ans + almost_everywhere_zero(int(str(n)[1:]), k-1)

