def one_square(n):
    return round(n ** .5) ** 2 == n

def two_squares(n):
    while n % 2 == 0: n //= 2
    p = 3
    while p * p <= n:
        while n % (p * p) == 0:
            n //= p * p
        while n % p == 0:
            if p % 4 == 3: return False
            n //= p
        p += 2
    return n % 4 == 1

def three_squares(n):
    while n % 4 == 0: n //= 4
    return n % 8 != 7

def sum_of_squares(n):
    if one_square(n): return 1
    if two_squares(n): return 2
    if three_squares(n): return 3
    return 4

from math import sqrt


def sum_of_squares(n):
    n_sqrt = int(sqrt(n))

    if n == n_sqrt * n_sqrt:
        return 1

    div, mod = divmod(n, 4)
    while mod == 0:
        div, mod = divmod(div, 4)
    if (div * 4 + mod) % 8 == 7:
        return 4

    for i in range(1, n_sqrt + 1):
        temp = n - i * i
        temp_sqrt = int(sqrt(temp))
        if temp == temp_sqrt * temp_sqrt:
            return 2

    return 3

