def f(n, unit):
    return [', ', '{} {}{}'.format(n, unit, 's' if n > 1 else '')]

def format_duration(seconds):
    if not seconds: return 'now'

    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    days, hours = divmod(hours, 24)
    years, days = divmod(days, 365)

    fs = []
    if years: fs.extend(f(years, 'year'))
    if days: fs.extend(f(days, 'day'))
    if hours: fs.extend(f(hours, 'hour'))
    if minutes: fs.extend(f(minutes, 'minute'))
    if seconds: fs.extend(f(seconds, 'second'))

    fs[-2] = ' and '
    fs.pop(0)
    return ''.join(fs)

def format_duration(s):
    dt = []
    for b, w in [(60, 'second'), (60, 'minute'), (24, 'hour'), (365, 'day'), (s+1, 'year')]:
        s, m = divmod(s, b)
        if m: dt.append('%d %s%s' % (m, w, 's' * (m > 1)))
    return ' and '.join(', '.join(dt[::-1]).rsplit(', ', 1)) or 'now'

def fibfusc(n, num_digits=None):
    if n < 2: return (1 - n, n)
    b = bin(n)[2:]

    x, y = fibfusc(int(b[0]))
    for bit in b[1:]:
        if bit == "1":
            x, y = (-y*(2*x + 3*y), (x + 2*y)*(x + 4*y))
        else:
            x, y = ((x + y) * (x - y), y * (2*x + 3*y))
        if num_digits:
            x, y = x % 10 ** num_digits - 10**num_digits, y % 10 ** num_digits
    return x, y

def fibfusc(n, num_digits=None):
    if n==0: return (1,0)
    x,y=0,1
    trunc=1 if num_digits==None else 10**(num_digits)
    nbin=bin(n)[3:]
    for i in nbin:
        x,y=((x+y)*(x-y),y*(2*x+3*y)) if i=='0' else (-y*(2*x + 3*y),(x + 2*y)*(x + 4*y))
        if trunc > 1 : x,y=(-(-x % trunc),y % trunc)   

    return x,y

def climb(n):
    r=[n]
    while(n>1):
        if n%2==0:
            n//=2
        else:
            n=(n-1)//2
        r.append(n)
    return r[::-1]

def fibfusc(n, num_digits=None):
    if n==0: return (1,0)
    r=climb(n)
    x,y=0,1
    for i in r[1:]:
        if i%2==0:
            if num_digits:
                x,y=((x+y)%(10**num_digits))*(x-y), y*((2*x+3*y)%(10**num_digits))
            else:
                x,y=(x+y)*(x-y), y*(2*x+3*y)
        else:
            if num_digits:
