@lru_cache()
def period(n):
    # see https://oeis.org/A216066 , comment by [Robert Pfister, Sep 12 2013]
    # and https://oeis.org/A003558 , formula by [Jonathan Skowera, Jun 29 2013]
    last = 1
    for i in range(n):
        val = abs(2 * n + 1 - 2 * last)
        if val == 1:
            return i + 1
        last = val

def string_func(s,x):
    x %= period(len(s))
    for __ in range(x):
        s = reversal_func(s)
    return s

def exp(permutation, n):
    result = [-1] * len(permutation)
    for i in range(len(permutation)):
        if result[i] == -1:
            j, cycle = i, []
            while True:
                cycle.append(j)
                j = permutation[j]
                if i == j: break
            for j, k in enumerate(cycle):
                result[k] = cycle[(j + n) % len(cycle)]
    return result

def string_func(s, n):
    m = len(s)
    perm = [i // 2 if i % 2 else m - 1 - i // 2 for i in range(m)]
    return ''.join(s[i] for i in exp(perm, n))

