import re

TOKENIZER = re.compile(r'(R+|F+|L+|\)|\()(\d*)')

def parseCode(code):
    cmds = [[]]
    for cmd,n in TOKENIZER.findall(code):
        s,r = cmd[0], int(n or '1') + len(cmd)-1
        if   cmd == '(': cmds.append([])
        elif cmd == ')': lst = cmds.pop() ; cmds[-1].extend(lst*r)
        else:            cmds[-1] += [(s, r)]
    return cmds[0]

def execute(code):

