                    newArr.append(arr[i])
                    i += 1
    else:
        i = length - 1
        while i >= 0:
            if isinstance(arr[i], list):
                newArr.append(unflatten_helper(arr[i], right))
                i -= 1
            else:
                rem = arr[i] % (i + 1)
                if rem > 2:
                    newArr.append(arr[i-rem+1:i+1])
                    i -= rem
                else:
                    newArr.append(arr[i])
                    i -= 1
        newArr = newArr[::-1]
    return newArr
def unflatten(flat_array, depth):
    left = True
    i = 0
    new_array = flat_array

    for d in range(depth):
        new_array = unflatten_list(new_array, left, i)
        left = not left
        if left:
            i = 0
        else:
            i = len(new_array) - 1
    return new_array

#true = left, false = right
def unflatten_list(array, direction, i):
    new_list = []
    while (direction == True and i < len(array)) or (direction == False and i >= 0):
        elem = array[i]
        if type(elem) == list:
            if direction:
                index = 0
                new_list.append(unflatten_list(elem, direction, index))
                i += 1
            else:
                index = len(elem) - 1
                new_list.insert(0,unflatten_list(elem, direction, index))
                i -= 1
        else:
            if direction:
                residual = elem  % (len(array) - i)
            else:
                residual = elem % (i + 1)
            if residual < 3:
                if direction:
                    new_list.append(elem)
                    i += 1
                else:
                    new_list.insert(0,elem)
                    i -= 1
            else:
                if direction:
                    if(i + residual <= len(array)):
                        new_list.append(array[i:i+residual])
                        i = i + residual
                    else:
                        new_list.append(array[i:])
                        i = len(array)
                else:
                    if(i - residual <= len(array)):
                        new_list.insert(0,array[i - residual + 1: i + 1])
                        i = i - residual
                    else:
                        new_list.insert(0,array[:i+1])
                        i = -1

    return new_list


def uf_f(arr):
    a, i = [], 0
    while i < len(arr):
        if isinstance(arr[i], list):
            a.append(uf_f(arr[i]))
            i += 1
        else:
            r = arr[i] % (len(arr) - i)
            if r < 3:
                a.append(arr[i])
                i += 1
            else:
                a.append(arr[i: i+r])
                i += r
    return a

def uf_r(arr):
    a, i = [], len(arr) - 1
    while i >= 0:
        if isinstance(arr[i], list):
            a.insert(0, uf_r(arr[i]))
            i -= 1
        else:
            r = arr[i] % (i + 1)
            if r < 3:
                a.insert(0, arr[i])
                i -= 1
            else:
                a.insert(0, arr[i-r+1: i+1])
                i -= r
    return a


def unflatten(array, depth):
    while depth:
        array = uf_f(array)
        depth -= 1
        if depth:
            array = uf_r(array)
            depth -= 1
    return array

def swap(s, a, b):
    s = list(s)
    s[a], s[b] = s[b], s[a]
    return ''.join(s)

def maximized_range(s, left): # Maximize value in range [left, end]
    return s[:left] + ''.join(sorted(s[left:], reverse=True))

def next_smaller(n):
    s = str(n)
    k = len(s)
    for i in range(k-1, -1, -1):
        for j in range(k-1, i, -1):
            if s[j] < s[i]:
                t = swap(s, i, j)
                if t[0] != '0':
                    return int(maximized_range(t, i+1))
    return -1

def next_smaller(n):
    num = list(str(n))

    try:
        pivot = next(i for i in reversed(range(len(num) - 1)) if num[i] > num[i + 1])
    except StopIteration:
        return -1
    swap  = next(i for i in reversed(range(len(num))) if num[pivot] > num[i])

    num[pivot], num[swap] = num[swap], num[pivot]
    num[pivot + 1:] = reversed(num[pivot + 1:])

    if num[0] == '0':
        return -1

    return int(''.join(num))

