class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        N = len(piles)
        cache = {}

        def recursive_game(start, M):
            score_left = sum(piles[start:])
            if start >= N: return 0
            if (start, M) in cache: return cache[(start,M)]
            if start + 2*M >= N: return score_left

            my_score = 0
            for x in range(1,2*M+1):
                opponent_score = recursive_game(start + x, max(M,x))
                my_score = max(my_score, score_left-opponent_score)

            cache[(start,M)] = my_score
            return my_score

        return recursive_game(0,1)

class Solution:
    def helper(self, n, M, curr, piles, memo):
        if curr >= n:
            return 0

        if n - curr <= 2*M:
            return sum(piles[curr:])

        if (curr, M) in memo:
            return memo[(curr, M)]

        me = 0
        total = sum(piles[curr:])

        for X in range(1, 2*M + 1):
            opponent = self.helper(n, max(X, M), curr + X, piles, memo)

            me = max(me, total - opponent)

        memo[(curr, M)] = me

        return me
    def stoneGameII(self, piles: List[int]) -> int:
        return self.helper(len(piles), 1, 0, piles, {})

