	n = len(t)
	if i < 0:
		return False
	if i >= n-1:
		return False

	tj1 = t[j2]
	tj2 = t[j1]

	ti = t[i]
	if i == j1:
		ti = tj1
	if i == j2:
		ti = tj2

	ti1 = t[i+1]
	if i+1 == j1:
		ti1 = tj1
	if i+1 == j2:
		ti1 = tj2

	if i % 2 == 0:
		return ti >= ti1
	else:
		return ti <= ti1


