    def __init__(self):
        self.arr = {}

    def insert(self, word):
        root = self
        for x in word:
            if x not in root.arr:
                root.arr[x] = Trie()
            root = root.arr[x]

    def dfs(self):
        if not len(self.arr):
            return False, True
        win, lose = False, False
        for x in self.arr:
            w, l = self.arr[x].dfs()
            win = win or not w
            lose = lose or not l
        return win, lose

