def union(s,n):
    i = 0
    while i < n:
        j = i+1
        while j < n:
            if s[i]&s[j]:
                s[i] = s[i]|s[j]
                del(s[j])
                n -= 1
            else:
                j += 1
        i += 1
    return s, n
