def inp():
    return [int(x) for x in input().split()]


def dfs(u, adj, visited, s, W, B):
    visited[u] = True
    total_w = W[u]
    total_b = B[u]
    s.append(u)
    for v in adj[u]:
        if not visited[v]:
            w, b = dfs(v, adj, visited, s, W, B)
            total_w += w
            total_b += b
    return total_w, total_b


def main():
