class Solution:
    def findKthPositive(self, arr: List[int], k: int) -> int:

        preNum = 0
        missNum = 0
        for currNum in arr:
            preMissNum = missNum
            missNum += currNum - preNum - 1
            if missNum >=k:
                res = preNum + k - preMissNum
                return res
            preNum = currNum

        res = preNum + k - missNum
        return res





class Solution:
    def findKthPositive(self, arr: List[int], k: int) -> int: # good 2, check the diff between idx and element, then compare to k, time O(logn), space O(1)
        l, r = 0, len(arr)-1
        while l<r: # find the last idx whose diff from the num is <k+1 
            m = (l+r)//2
