             if A[i] == B[0]:
                 divisible = True if (len(B)-(len(A)-i))%len(A) == 0 else False
                 time = 1 + (len(B)-(len(A)-i))//len(A) if divisible else 1 + (len(B)-(len(A)-i))//len(A) + 1
