     def canPlaceFlowers(self, flowerbed, n):
         """
         :type flowerbed: List[int]
         :type n: int
         :rtype: bool
         """
         if n == 0:
             return True
         L = len(flowerbed)
         if n > (L + 1) // 2:
             return False
         if L == 1:
             return flowerbed[0] == 0

         cnt, i = 0, 0
