                 tmp = k
             ttmp = tmp    
             while ttmp!= 0:
                 ret += s[i+ttmp-1]
                 ttmp -= 1

             i+=tmp
             if len(s)-i < k:
                 tmp = len(s)-i
             else:
                 tmp = k
             ttmp = tmp

             while ttmp!= 0:
                 ret += s[i]
                 i+=1
                 ttmp -= 1

         return ret

class Solution:
     def reverseStr(self, s, k):
         """
         :type s: str
         :type k: int
         :rtype: str
         """
         n = len(s)
         p = 0

         s = list(s)

         while True:
             if p >= n:
                 break
             p1 = p + k
             if p1>n:
                 p1 = n
             p0 = p
             while p0 < p1:
                 p1-=1
                 s[p0], s[p1] = s[p1],s[p0]
                 p0+=1
             p += k*2
         return ''.join(s)

class Solution:
     def reverseStr(self, s, k):
         """
         :type s: str
         :type k: int
         :rtype: str
         """
         for idx in range(0, len(s), 2*k):
             s = s[:idx] + s[idx:idx+k][::-1] + s[idx+k:]
         return s

