class Solution:
    def toGoatLatin(self, S: str) -> str:

        vowels = set(['a','e','i','o','u'])
        s = ''
        for i,item in enumerate(S.strip().split()):
            if item[0].lower() in vowels:
                s+=item
            else:
                s+=item[1:]+item[0]

            s+='ma'+'a'*(i+1)+' '

        return s[:-1]

class Solution:
    def toGoatLatin(self, S: str) -> str:
        words = S.split(' ')
        def trans(word):
            ret = ''
            if word[0] in ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']:
                ret = word + 'ma'
            else:
                    ret = word[1:] + word[0] + 'ma'
            return ret
        ret = [trans(x) for x in words]
        for idx in range(len(ret)):
            ret[idx] += 'a' * (idx + 1)
        return ' '.join(ret)

