class Solution:
     def findUnsortedSubarray(self, nums):
         """ Improved algorithm.
         Time complexity: O(n). Space complexity: O(1).
         """
         n = len(nums)
         # special case
         if n < 2:
             return 0

         # find index of the min number of the unsorted subarray from the left
         left = n - 1
         for i in range(n - 1):
             if nums[i] > nums[i + 1]:
                 left = i + 1
                 break
         min_i = left
         for i in range(left + 1, n):
             if nums[i] < nums[min_i]:
                 min_i = i

         # find index of max number of the unsorted subarray from the right
         right = 0
         for i in range(n - 1, 0, -1):
             if nums[i] < nums[i - 1]:
                 right = i - 1
                 break
         max_i = right
         for i in range(max_i - 1, -1, -1):
             if nums[i] > nums[max_i]:
                 max_i = i

         # find the correct position of number at min index
         for i in range(min_i):
             if nums[i] > nums[min_i]:
                 min_i = i
                 break

         # find the correct position of number at max index
         for i in range(n - 1, max_i, -1):
             if nums[i] < nums[max_i]:
                 max_i = i
                 break

         # return length of unsorted subarray
         length = max_i - min_i + 1
         return length if length > 0 else 0
class Solution:
     def findUnsortedSubarray(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         left = 1
         size = len(nums)
         if size == 0:
             return 0
         while left < size and nums[left - 1] <= nums[left]:
             left += 1
         if left == size:
             return 0
         left -= 1
         right = size - 1
         while right > 0 and nums[right] >= nums[right - 1]:
             right -= 1
         sub = nums[left : right + 1]
         min_ = min(sub)
         max_ = max(sub)
         for i in range(left):
             if nums[i] > min_:
                 left = i
                 break
         for i in range(size - 1, right, -1):
             if nums[i] < max_:
                 right = i
                 break
         return right - left + 1
class Solution:
     def findUnsortedSubarray(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         sort_nums = sorted(nums)
         diff = list(map(lambda x, y: x - y, sort_nums, nums))
         start, end = 0, len(nums) - 1
         while start < end:
             if diff[start] == 0:
                 start += 1

             if diff[end] == 0:
                 end -= 1

             if diff[start] and diff[end]:
                 break

         if end > start:
             return end - start + 1
         else:
             return 0

