class Solution:
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:

        if start > destination: 
            start, destination = destination, start 

        sum1 = sum(distance[start:destination])
        sum2 = sum(distance) - sum1 

        return min(sum1, sum2)

class Solution:
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:
        clockwise = 0
        i = start
        while i != destination:
            clockwise += distance[i]
            if i == len(distance) - 1:
                i = 0
            else:
                i += 1

        i = start
        counterclockwise = 0
        while i != destination:

            if i == 0:
                i = len(distance) - 1
            else:
                i -= 1
            counterclockwise += distance[i]

        return min(clockwise, counterclockwise)

class Solution:
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:
        if start == destination:
            return 0

        if start > destination:
            start, destination = destination, start

        increase = start
        decrease = start
        right = 0
        left = 0

        while True:
            index = (increase) % len(distance)
            increase += 1
            if(index == destination):
                break;
            right += distance[index]

        while True:
            decrease -= 1
            index = (decrease) % len(distance)
            left += distance[index]
            if(index == destination):
                break;

        return min(left, right)

class Solution:
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:

        total = sum(distance)

        journey = 0
        while start % len(distance) != destination:
            journey += distance[start % len(distance)]           
            start += 1

        return min(journey,total-journey)

