def inverseMod(a, m):
    r1, s1, r2, s2 = a, 1, m, 0
    while r2>0:
        q = r1//r2
        r1, s1, r2, s2 = r2, s2, r1-q*r2, s1-q*s2
    if r1==1:
        return s1%m

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def inverse_mod(a, b):
    if gcd(a, b) != 1:
        return None
    x, y, B = 1, 0, b
    while a > 1: 
        q = a // b
        a, b = b, a % b
        x, y = y, x - q * y
    return x + B if x < 0 else x

inverseMod = lambda a, b: inverse_mod(a, b)

def gcd_ext(a, b):
    if b == 0:
        return 1, 0, a
    else:
        x, y, gcd = gcd_ext(b, a % b)
        return y, x - y*(a//b), gcd


def inverseMod(a, n):
    x, y, gcd = gcd_ext(a, n)
    if gcd == 1:
        return x % n
    else:
        return None

