def is_balanced(s, caps):
    stack = []
    openers, closers = caps[::2], caps[1::2]
    for char in s:
        if char in openers:
            if char in closers and stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        elif char in closers:
            if not stack or openers[closers.index(char)] != stack[-1]:
                return False
            else:
                stack.pop()
    return not stack

def is_balanced(s, caps):
    s = ''.join(i for i in s if i in caps)
    caps = [caps[i:i+2] for i in range(0,len(caps),2)]
    prev = ''
    while s != prev:
        prev = s
        for c in caps:
            s = s.replace(c,'')
    return not s

