def test(s, n):
    for k in range(2, len(s)+1):
        c = s[k-1]
        if c == 'D':
            if n % k != 0: return False
        else:
            if (gcd(n, k) == 1) != (c == 'P'): return False
    return True

def find_primes(n):
    if n < 2: return
    yield 2
    s = list(range(1, n+1, 2))
    mroot = int(n ** 0.5)
    half = (n+1) // 2
    i = 1
    m = 3
    while m <= mroot:
        if s[i]:
            yield s[i]
            j = m*m // 2
            while j < half:
                s[j] = 0
                j += m
        i += 1
        m += 2
    for x in s[i:]:
        if x:
            yield x

