def process(s):
    if isinstance(s, bytes):
        s = s.decode('utf-8')
    punct = '.!,;:?'
    s = s.translate(str.maketrans(punct, ' ' * len(punct)))
    s = unicodedata.normalize('NFD', s).encode('ascii', 'ignore')
    return s.lower()

