def cost_of_carpet(room_length, room_width, roll_width, roll_cost):
    if room_length > roll_width < room_width or room_length * room_width <= 0:
        return 'error'
    if room_length <= roll_width >= room_width:
        side = min(room_length, room_width)
    else:
        side = max(room_length, room_width)
    return round(side * roll_width * roll_cost, 2)

def cost_of_carpet(room_length, room_width, roll_width, roll_cost):
  if room_length <= 0 or room_width <= 0 or (room_length > roll_width < room_width):
      return 'error'

  x, y = min(room_length, room_width), max(room_length, room_width)

  if y > roll_width:
      return round(y * roll_width * roll_cost, 2)

  return  round(x * roll_width * roll_cost, 2)

def cost_of_carpet(room_length, room_width, roll_width, roll_cost):
    if 0 in [room_length, room_width]:
        return "error"
    mi, mx = min((room_length, room_width)), max((room_length, room_width))
    rw, rc = roll_width, roll_cost
    return round(mi * rw * rc, 2) if mx <= roll_width else (round(mx * rw * rc, 2) if roll_width >= mi else "error")

