def combs_non_empty_boxesII(n):
    MAX_BALL = 2 + 1800
    DP, lst = [None], [0, 1]
    for _ in range(MAX_BALL):
        DP.append([sum(lst), *max((v, i) for i, v in enumerate(lst))])
        lst.append(0)
        lst = [v * i + lst[i - 1] for i, v in enumerate(lst)]
    if n < 0 or n >= len(DP):
        raise IndexError("Index out of range")
    return DP[n]

