def combs_non_empty_boxesII(n):
    tot, max, index = 0, 1, 1
    for ix in range(len(S[n-1])):
        val = S[n-1][ix]
        tot = tot + val
        if val >= max:
            max = val
            index = ix
    return [tot, max, index+1]

