def complete_binary_tree(a):
    res, queue = [], [a]
    while queue:
        L = queue.pop(0)
        m = mid(len(L))
        res.append(L[m])
        if m: queue.append(L[:m])
        if m < len(L)-1: queue.append(L[m+1:])
    return res

def complete_binary_tree(a):
    def in_order(n=0):
        if n < len(a):
            yield from in_order(2 * n + 1)
            yield n
            yield from in_order(2 * n + 2)

    result = [None] * len(a)
    for i, x in zip(in_order(), a):
        result[i] = x
    return result

def complete_binary_tree(a):
    def calculate(a, root = 1, cnt = 0, output = []):
        idx = list(range(1, len(a)+1))
        if (not output):
            output = [0] * len(a)

        if (root * 2 in idx):
            cnt, output = calculate(a, root = root * 2, cnt = cnt, output = output)

        output[root-1] = a[cnt]
        cnt += 1

        if (root * 2 + 1 in idx):
            cnt, output = calculate(a, root = root * 2 + 1, cnt = cnt, output = output)

        return cnt, output
    return calculate(a)[1]

