def prime_factorization(number):
    if number in PRIMES:
        return []
    result = []
    prime_factors = [prime for prime in PRIMES if number % prime == 0]
    for factor in prime_factors:
        while number % factor == 0:
            result.append(factor)
            number = number // factor
    return result

