    seens = set()
    while number > 1:
        # print('number:', number)
        sum_squares = _sum_squares(number)
        # print('sum_squares:', sum_squares)
        if sum_squares in seens:
            return False
        seens.add(sum_squares)
        # print('seens:', seens)
        number = sum_squares
    return True

