def interpreter(tape):
    selector = 0
    output = ""
    array = [0]
    commandIndex = 0

    while(True):
      command = tape[commandIndex%len(tape)]

      if command == '>':
        selector+=1;
        if selector == len(array):
          array.append(0)

      if command == '<':
        if selector == 0:
          array = [0] + array  
        else:
          selector-=1;

      if command == '+':
        array[selector]+=1;
        if array[selector] == 256:
          array[selector] = 0
      if command == '-':
        array[selector]-=1;
        if array[selector] == -1:
          array[selector] = 255
      if command == '/':
        if array[selector] == 0:
          commandIndex += 1
      if command == '\\':
        if array[selector] != 0:
          commandIndex += 1
      if command == '*':
        output = output + chr(array[selector])
      if command == '&':
        return output        
      commandIndex+=1  
    return output

import itertools

def interpreter(tape):    
    cells, cell, out, skip = {}, 0, '', False
    for c in itertools.cycle(tape):
        if not skip:
            if c == '>': cell += 1
            if c == '<': cell -= 1
            if c == '+': cells[cell] = 1 if cell not in cells else 0 if cells[cell] == 255 else cells[cell] + 1
            if c == '-': cells[cell] = 255 if cell not in cells else 255 if cells[cell] == 0 else cells[cell] - 1
            if c == '*': out += chr(cells.get(cell, 0))
            if c == '&': break
        skip = (c == '/' and cells.get(cell, 0) == 0) or (c == '\\' and cells.get(cell, 0))
    return out

def interpreter(tape):
    data, pos, res = [0 for i in range(tape.count('*'))], 0, ""
    while 1:
        try:
            for i in iter([i for i in tape]):
                if   i == "+": data[pos] = (data[pos] + 1) %256
                elif i == "-": data[pos] = (data[pos] - 1) %256
                elif i == ">": pos += 1
                elif i == "<": pos -= 1
                elif i == "*": res += chr(data[pos])
                elif i == "/" and data[pos] == 0: next(tape)
                elif i == "\\" and data[pos] != 0: next(tape)
                elif i == "&": return res
        except:
            pass

