def join_lesser(fig):
    width = len(fig[-1]) + 1
    result = []
    for line in fig:
        padding = ' ' * (width // 2)
        result.append(padding + line + padding)
    for line in fig:
        result.append(line + ' ' * (width - len(line)) + line)
    return result


