    if tup[0] != 2: yield tup

    if len(tup) > 2:
        for i,a in enumerate(tup):
            for j,b in enumerate(tup[i+1:],i+1):
                m = a*b
                t = tuple(sorted(tup[:i] + tup[i+1:j] + tup[j+1:] + (m,)))
