def string_parse_gen(string):
    counter, prev_char = 0, ''
    for char in string:
        if char == prev_char:
            counter += 1
            if counter == 2:
                yield '['
        else:
            if counter >= 2:
                yield ']'
            prev_char = char;
            counter = 0;
        yield char;

    if counter >= 2:
        yield ']'


