def isPP(n):
    base = 2
    power = 2

    while base ** power <= n:
        while base ** power <= n:
            if base ** power == n:
                return [base, power]
            else:
                power += 1

        power = 2
        base += 1

    return None

def isPP(n):
    x, y = 2, 2
    while x**2 <= n:
        if x**y == n:
            return[x,y]
        if x**y > n:
            x+=1
            y = 1
        y+=1        
    return None

def isPP(n):
    m, k = 2, 2
    while m**2 <= n:
        while m**k <= n:
            if m**k == n:
                return [m, k]
            else:
                k += 1
        m += 1
        k = 2
    return None

def isPP(n):
    for i in range(2, n+1):
        for j in range(2, n+1):
            if i**j > n:
                break
            elif i**j == n:
                return [i, j]
    return None

