def de_nico(key,msg):
    sorted_key = sorted(key)
    num_key = []
    for chr in key:
        num_key.append(sorted_key.index(chr))

    result = ''
    start = 0
    end = len(key)
    while start < len(msg):
        chunk = msg[start : end]
        for index in num_key:
            if index < len(chunk):
                result += chunk[index]
        start = end
        end += len(key)

    return result.strip()

def de_nico(key, msg):
    ll, order, s = len(key), [sorted(key).index(c) for c in key], ''
    while msg:
        s, msg = s + ''.join(msg[i] for i in order if i < len(msg)), msg[ll:]
    return s.strip()

def de_nico(key,msg):
    result = ''
    counter = -1
    while len(result) < len(msg):
        counter += 1
        for i in [sorted(key).index(c) for c in key]:
            try:
                result += msg[i+counter*len(key)]
            except:
                continue
    return result.strip()

