def cog_RPM(cogs, n):
    return [
        cogs[n] / cogs[0] * (-1 if n % 2 else 1),
        cogs[n] / cogs[-1] * (1 if (len(cogs) - n) % 2 else -1),
    ]

def cog_RPM(cogs, n):
    a,b=1,1
    if n%2==1:
        a = -1
    if len(cogs)%2==n%2:
            b = -1
    return [a*cogs[n]/cogs[0],b*cogs[n]/cogs[-1]]

def cog_RPM(cogs, n):
    output = []
    if n % 2 == 0:
        a = 1
        if (len(cogs) % 2-1) == 0:
            b = 1
        else:
            b = -1
    else:
        a = -1
        if (len(cogs)-1) % 2 == 0:
            b = -1
        else:
            b = 1
    output.append(cogs[n]/cogs[0]*a)
    output.append(cogs[n]/cogs[-1]*b)
    return output

