        if s[-1] == 'x':
            self.p = 1
            s = s[:-1]
        if 0 < len(s):
            self.a *= int (s)

    def __add__(self, other):
        if self.p == other.p:
            self.a += other.a
            return self
        else:
            return Equ([self, other])

    def __sub__(self, other):
        if self.p == other.p:
            self.a -= other.a
            return self
        else:
            return Equ([self, Exp("-1") * other])

    def __mul__(self, other):
        self.p += other.p
        self.a *= other.a
        return self

    def __div__(self, other):
        self.p -= other.p
        self.a /= other.a
        return self

    def __str__(self):
