def roundRobin(jobs, sl, index):
    start_sum = sum(jobs)
    cur_idx = 0
    while jobs[index] > 0:
        jobs[cur_idx] = jobs[cur_idx] - min(jobs[cur_idx], sl)
        cur_idx = (cur_idx + 1) % len(jobs)
    return start_sum - sum(jobs)

def roundRobin(jobs, slice, index):
    total_cc = 0
    while True:
        for idx in range(len(jobs)):
            cc = min(jobs[idx], slice)
            jobs[idx] -= cc
            total_cc += cc
            if idx == index and jobs[idx] == 0:
                return total_cc

def roundRobin(jobs, limit, target):
    queue = list(enumerate(jobs))
    cycles = 0
    while True:
        index, job = queue.pop(0)
        if limit >= job:
            cycles += job
            job = 0
        else:
            job -= limit
            cycles += limit
        if job:
            queue.append((index, job))
        elif index == target:
            break
    return cycles

