from collections import Counter

def getAllPrimeFactors(n):
    # errors and zero
    if not type(n) == int or n < 1:
        return []

    # edge cases
    if n in (1, 2):
        return [n]

    # factorisation
    factors = []

    for p in PRIMES:
        if p*p > n:
            break
        while n % p == 0:
            n //= p
            factors.append(p)

    return factors + [n] * (n > 1)


