    factors = Counter(getAllPrimeFactors(n))
    return [ list(factors.keys()), list(factors.values()) ]


def getUniquePrimeFactorsWithProducts(n):
    factors = Counter(getAllPrimeFactors(n))
    return [ p**e for p, e in factors.items() ]

