        for i in range(d, int(m**0.5) + 1):
            if m % i == 0:
                res.append(store + [i] + [m // i])
                stack.append([m // i, i, store + [i]])
    filtred_res = list(filter(lambda x: len(x) == s, res))
    if filtred_res:
        return [len(res), len(filtred_res), filtred_res] if len(filtred_res) > 1 else [len(res), len(filtred_res), filtred_res[0]]
    else:
        return [len(res), 0, []]

def prod_int_partII(n, s, min_=2):
    total, fac = 0, []
    for d in range(min_, int(n ** .5) + 1):
        if not n % d:
            count, l, sub = prod_int_partII(n // d, s-1, d)
            if l == 1: sub = [sub]
            total += count + 1
            fac.extend([d] + x for x in sub)
    if s == 1: fac = [[n]]
    return [total, len(fac), fac[0] if len(fac) == 1 else fac]

def prod_int_partII(n, s):
    part = list(mul_part_gen(n))[:-1]
    sub = [p for p in part if len(p) == s]
    return [len(part), len(sub), sub[0] if len(sub) == 1 else sub]

def mul_part_gen(n, k=2): 
    if n == 1: 
        yield [] 
    for i in range(k, n+1): 
        if n % i == 0: 
            for part in mul_part_gen(n//i, i): 
                yield [i] + part

