import re

def spreadsheet(s):
    numbers = re.findall(r"(\d+)", s)
    if len(numbers) == 1:
        row = numbers[0]
        col = sum(26**i * (ord(v)-64) for i, v in enumerate(s[:s.find(row)][::-1]))
        return "R{row}C{col}".format(row=row, col=col)
    else:
        row = numbers[0]
        x = int(numbers[1])
        col = ""
        while x > 0:
            col = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[(x-1)%26] + col
            x = (x-1) // 26
        return "{col}{row}".format(col=col, row=row)

import re

def to_display(b, n):
    r = []
    while n:
        n, x = divmod(n - 1, 26)
        r.append(chr(65 + x))
    return "".join(r[::-1]) + str(b)

def to_internal(s):
    (a, b), n = re.findall(r"[A-Z]+|\d+", s), 0
    for x in a:
        n *= 26
        n += ord(x) - 64
    return (int(b), n)

def spreadsheet(s):
    a = re.findall(r"[A-Z]+|\d+", s)
    return "R{}C{}".format(*to_internal(s)) if len(a) == 2 else to_display(int(a[1]), int(a[3]))

import re

def spreadsheet(s):
    nums = re.findall(r'(\d+)', s)
    if len(nums) == 2:
        n, cStr = int(nums[1]), ''
        while n:
            n, r = divmod(n-1, 26)
            cStr += chr(r + 65)
        return "{}{}".format(cStr[::-1], nums[0])
