def black_and_white(height, width, compressed):
    res, left, i, color = [], 0, 0, 0
    for h in range(height):
        tot, tmp = 0, []
        if color == 1: tmp.append(0)
        while tot < width and i < len(compressed):
            if left:
                if left <= width:
                    tmp.append(left)
                    tot, left, color = left, 0, 1-color
                else:
                    tmp.append(width)
                    tot, left = width, left-width
            else:
                i, val = i+1, compressed[i]
                if tot + val <= width:
                    tmp.append(val)
                    tot, color = tot+val, 1-color
                else:
                    tmp.append(width-tot)
                    tot, left = width, tot+val-width
        if len(tmp)%2: tmp.append(left if h == height-1 else 0)
        res.append(tmp)
    return res

from itertools import takewhile
from typing import List


def black_and_white(height: int, width: int, compressed: List[int]) -> List[List[int]]:
    def tracker():
        is_black = False
        line = 0
        for i in compressed:
            is_black = not is_black
            if line + i < width:
                yield i
                line += i
            else:
                yield width - line
                if is_black:
                    yield 0
                yield -1
                i -= width - line
                line = 0
                while i > width:
                    if is_black:
                        yield width
                        yield 0
                    else:
                        yield 0
                        yield width
                    yield -1
                    i -= width
                if i == 0 and is_black:
                    yield 0
                if i > 0:
                    if is_black:
                        yield i
                    else:
                        yield 0
                        yield i
                    line += i

    it = iter(tracker())
    return [[i for i in takewhile(lambda i: i >= 0, it)] for h in range(height)]

