def looper(start, stop, number):
    if number == 1:
        return [start]
    elif number == 2:
        return [start, stop]        

    increment = (stop - start) / (number - 1)   

    arr = []
    for n in range(0, number - 1):
        new_element = start + n * increment
        arr.append(new_element)

    arr.append(float(stop))
    return arr

def looper(start, stop, number):
    c,r,s=0,[],(stop-start)/(number-(1 if number>1 else 0))
    while c<number:
      r.append(start+c*s)
      c+=1
    if number>1: r.pop(); r.append(stop)
    return r

def iter(start, number, step):
    for i in range(number-1):
        yield float(start + step*i)

def looper(start, stop, number):
    if number == 1:
        return [start]

    step = (stop - start) / (number - 1)
    lt = list(iter(start, number, step))
    lt.append(stop)
    return lt

