def binary_simulation(Q,S) :
    Q,L,R = int(Q,2),len(Q),[]
    for S in S :
        if S[0] < 'L' :
            Q ^= (1 << L - S[1] + 1) - 1
            Q ^= (1 << L - S[2]) - 1
        else :
            R.append('1' if Q & (1 << L - S[1]) else '0')
    return R

def binary_simulation(s, q):
    n=int(s[::-1],2)
    r=[]
    for x in q:
        if x[0]=='I':
            _,a,b=x
            n^=((1<<(b-a+1))-1)<<(a-1)
        else:
            _,a=x
            r+=['01'[n&(1<<(a-1))>0]]
    return r

def binary_simulation(s, q):
    s = '0'+s
    ans = []
    for val in q:
        if val[0] == 'I':
            s = s[:val[1]] + s[val[1] : val[2]+1].translate(''.maketrans('01', '10')) + s[val[2]+1:]
        elif val[0] == 'Q':         
            ans.append(s[val[1]])         
    return ans

def binary_simulation(s, q):
    x, l, result = int(s, 2), len(s), []
    for op in q:
        if op[0] == 'I':
            i, j = op[1:]
            x ^= (1 << j-i+1)-1 << l-j
        else:
            result.append(str(x >> l-op[1] & 1))
    return result

def binary_simulation(s, q):

    outlst=[]
    for op in q:
        ini=op[1]-1

        if op[0]=='Q':
            outlst.append(s[ini])
        elif op[0]=='I':
            transl=s[ini:op[2]].maketrans('01','10')
            s=s[:ini]+s[ini:op[2]].translate(transl)+s[op[2]:]
    return outlst

