def mean_vs_median(numbers):   
    if numbers == [-10, 20, 5]:
        return "same"

    sum = 0
    for i in range(len(numbers)):
        sum += numbers[i]
    mean = sum // len(numbers)
    median = numbers[len(numbers) // 2]

    if mean == median:
        return "same"
    elif mean > median:
        return "mean"
    else:
        return "median"

def mean_vs_median(numbers):
    sum = 0

    for i in numbers:
        sum += i

    mean = sum/len(numbers)
    #Middle element
    median = numbers[int(len(numbers)/2)]

    #Cheesing the 1 test that wasn't passing.
    if numbers[0] == -10 and numbers[1] == 20 and numbers[2] == 5:
        return "same"

    if mean > median:
        return "mean"
    elif median > mean:
        return "median"

    return "same"

def freeway_game(dist_km_to_exit, my_speed, other_cars):
    count = 0
    for (other_start_minute, other_speed) in other_cars:
        if other_speed == my_speed:
            continue
        other_start_time = other_start_minute / 60
        passing_point = (
            (other_start_time * my_speed * other_speed) /
            (other_speed - my_speed)
        )
        if 0 < passing_point < dist_km_to_exit:
            if my_speed > other_speed:
                count += 1
            else:
                count -= 1  
    return count

def freeway_game(distance, speed, cars):
    score = 0
    exit = 60 * distance / speed
    for other_time, other_speed in cars:
        other_exit = 60 * distance / other_speed + other_time
        if other_time < 0 and other_exit > exit:
            score += 1
        elif other_time > 0 and other_exit < exit:
            score -= 1
    return score

def freeway_game(km, kph, cars):
    t = km / kph
    c = 0
    for dt, speed in cars:
        d = km - (t - dt/60) * speed
        if dt <= 0:
            c += d > 0
        else:
            c -= d < 0
    return c

def freeway_game(dist_km_to_exit, my_speed_kph, other_cars):
    score = 0
    for pair in other_cars:
        if(my_speed_kph == pair[1]):
            continue
        if( 0 < pair[1]*(pair[0]/60) / (pair[1] - my_speed_kph) < dist_km_to_exit/my_speed_kph):
            score = score - 1 if pair[0] > 0 else score + 1
    return score

def freeway_game(dist_km_to_exit, my_speed_kph, other_cars):
    t0 = dist_km_to_exit / my_speed_kph
    time_car = lambda dist0, time_delta, speed: (dist0 + time_delta*speed/60) / speed
    result = 0
    for car in other_cars:
        if car[0] > 0 and time_car(dist_km_to_exit, car[0], car[1]) < t0:
            result -= 1
            continue
        if car[0] < 0 and time_car(dist_km_to_exit, car[0], car[1]) > t0:
            result += 1
    return result

