def nb_common_div(s):
    l = len(s)
    s1 = sum(int(''.join(v)) for i in range(l) for v in combinations(s, i+1))
    s2 = sum(int(''.join(s[i:j+1])) for i in range(l) for j in range(i, l))
    f1, f2 = factors(s1), factors(s2)
    return len(f1 & f2)

