def valid_parentheses(string):

    open = 0

    for c in string:

        # increase open count for an open parenthesis
        if c == "(":
            open += 1

        # descrease open count for a closing parenthesis
        elif c == ")":
            open -= 1

        # if the open count ever drops below zero, parentheses are invalid    
        if open < 0:
            return False

    # if open ends up non-zero, this returns False, otherwise True
    return open == 0

def valid_parentheses(string):
    depth = 0                           #Depth increases as we go 'deeper in parentheses', and decreases when parentheses are closed.
    for i in string:
        if i == "(":
            depth += 1
        elif i == ")":
            depth -= 1
        if depth < 0:
            return False                #If at some point depth becomes negative, we've met a situation, when the parentheses pair can't be closed - sequence is not valid
    if depth == 0:                      #At the end of valid sequence all opening parentheses' amount must be equal to the closing ones'.
        return True
    else:
        return False

