def shortest_time(n, m, speeds):
    if n == 1:
        return 0
    else:
        move,open,close,walk=speeds
        elevator = abs(n-m)*move+open+close+move*(n-1)+open
        walking = walk*(n-1)
    return min(elevator, walking)

def shortest_time(n, m, speeds):
    lift, open, close, walk = speeds
    return min(
            # taking the elevator
            abs(m - n) * lift + open + close + (n - 1) * lift + open,
            # walking
            (n - 1) * walk
            )

def shortest_time(n, m, speeds):
    a, b, c, d = speeds
    return min(d * (n - 1), (abs(m - n) + n - 1) * a + 2 * b + c)

def shortest_time(n,m,speeds):
    a,b,c,d = speeds
    return min((n-1)*d, a*(abs(m-n) + n-1) + 2*b + c)

def shortest_time(n, m, speeds):
    a, b, c, d = speeds
    elevator = (abs(m - n) + n - 1) * a + b * 2 + c
    walk = (n - 1) * d
    return min(elevator, walk)

