def bubblesort_once(arr):

    new_arr = arr.copy()
    for i in range(len(new_arr)-1):
        if new_arr[i]>new_arr[i+1]:
            new_arr[i], new_arr[i+1] = new_arr[i+1], new_arr[i]
    return new_arr

def bubblesort_once(l):
    values = l[:]
    for i in range(0, len(values) - 1):
        first = values[i]
        second = values[i + 1]
        if(first > second ):
            values[i + 1] = first
            values[i] = second
    return values

