    while s < h:
        h -= 1
        s = sigma(h)
    return [[h], [s-h]]

def sigma(x):
    sq,s,i = x**.5,1,2
    while i<=sq :
        if x%i==0 : s += i+x/i
        if i==sq  : s -= i
        i += 1
    return s

def ab(n):
    s = 1
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            s += i
            if i * i != n:
                s += n // i
    return s - n

