    b = ord(s[-1]) - ord(s[0]) if s else 0
    c = (a | b) & (~a << 2)
    return c ^ (32 * (s.count(' ') + 1))

def string_hash(s):
    a = sum(ord(c) for c in s)
    b = sum(ord(x) - ord(y) for x,y in zip(s[1:], s))
    c = (a | b) & ((~a) << 2)
    return c ^ ((s.count(" ") + 1) << 5)

def string_hash(s):
    t = tuple(map(ord, s))
    a, b = sum(t), sum(y - x for x, y in zip(t, t[1:]))
    return (a | b) & (~a << 2) ^ 32 * (s.count(' ') + 1)

