    if len(vowels) == 0:
        return ''.join(text)
    while n != 0:
        if n > 0:
            vowels.insert(0, vowels.pop(-1))
            n -= 1
        else:
            vowels.insert(len(vowels) - 1, vowels.pop(0))
            n += 1
