def isCandidate(x, seq):
    count = 0
    left_pointer = 0
    right_pointer = len(seq) - 1

    while left_pointer < right_pointer:
        left = seq[left_pointer]
        right = seq[right_pointer]

        if left + right == x:
            count += 1
            if count == 2:
                return False

        if left + right > x:
            right_pointer -= 1
            left_pointer = 0
            continue

        left_pointer += 1

    return count == 1

def ulam_sequence(u0, u1, n):
    seq = [u0, u1]
    x = u0 + u1
    while len(seq) < n:
        if isCandidate(x, seq):
            seq.append(x)        
        x += 1
    return seq

def ulam_sequence(U,V,Q) :
    R = [U,V]
    S = [U + V]
    while len(R) < Q :
        while 1 < len(S) and S[-1] == S[-2] :
            T = S.pop()
            while T == S[-1] : S.pop()
        T = S.pop()
        S.extend(T + V for V in R)
        R.append(T)
        S.sort(reverse = True)
    return R

