import string

def insert_missing_letters(st):
    tbl = dict.fromkeys(map(ord, st.upper()))
    result = []
    seen = set()
    for c in st:
        if c not in seen:
            seen.add(c)
            c += string.ascii_uppercase[string.ascii_lowercase.find(c) + 1:].translate(tbl)
        result.append(c)
    return ''.join(result)

def insert_missing_letters(word):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    new = ''
    used = ''

    for letter in set(word):
        alphabet = alphabet.replace(letter,"")

    for letter in word:
        if letter not in used:
            new += letter + "".join([x.upper() for x in alphabet if ord(x) > ord(letter)])
        else: new += letter

        used += letter

    return new

