from itertools import chain


def mark_spot(n):
    if not (isinstance(n, int) and n % 2 and n > 0):
        return '?'
    result = []
    row_length = n * 2 - 1
    for a in chain(range(0, n, 2), range(n - 3, -1, -2)):
        row = [' '] * row_length
        row[a] = 'X'
        row[-(a + 1)] = 'X\n'
        result.append(''.join(row).rstrip(' '))
    return ''.join(result)

