def robot_walk(a):
    if len(a)<=3:
        return False
    left,upper,right,lower=0,a[0],a[1],a[0]-a[2]
    for i,x in enumerate(a[3:]):
        m=move[i%4]
        if m=='left':
            if right-x<=left:
                return True
            left=right-x
        elif m=='up':
            if lower+x>=upper:
                return True
            upper=lower+x
        elif m=='right':
            if left+x>=right:
                return True
            right=left+x
        elif m=='down':
            if upper-x<=lower:
                return True
            lower=upper-x
    return False

from itertools import cycle

def robot_walk(walks):
    dyx = cycle([(1, 0, 'N'), (0, 1, 'E'), (-1, 0, 'S'), (0, -1, 'W')])
    ymin, ymax = -1, float('inf')
    xmin, xmax = 0, float('inf')
    cy, cx = 0, 0
    for w in walks:
        dy, dx, d = next(dyx)
        cy, cx = cy+dy*w, cx+dx*w
        if d == 'N':
            if cy >= ymax:
                return True
            ymax = cy
        elif d == 'E':
            if cx >= xmax:
                return True
            xmax = cx
        elif d == 'S':
            if cy <= ymin:
                return True
            ymin = cy
        elif d == 'W':
            if cx <= xmin:
                return True
            xmin = cx
    return False

