def switch_endian(n, bits):
    if not (bits >= 8 and bits & bits - 1 == 0 and bits >= n.bit_length()):
        return None
    return int.from_bytes(n.to_bytes(bits // 8, 'little'), 'big')

# Switch the endianness of integer n
# Assume 64-bit unsigned integers
def switch_endian(n, bits):
    if n<0 or bits&(bits-1) or bits<8 or n>=2**bits:
        return None
    result = 0
    for _ in range(bits//8):
        result = (result<<8) | (n&255)
        n >>= 8
    return result

# Bitwise operators? What's that? Don't need it
def switch_endian(n, bits):
    if not (0 <= n < 2**bits and bits == 2**(bits.bit_length()-1)): return
    x = f"{n:0{bits}b}"
    return int(''.join(x[i-8:i] for i in range(bits, 0, -8)), 2)

def compare(s1, s2):
    s1, s2 = s1.split('.'), s2.split('.')
    if len(s1) < len(s2):
        s1 += ['0'] * (len(s2) - len(s1))
    elif len(s1) > len(s2):
        s2 += ['0'] * (len(s1) - len(s2))
    for i in range(len(s2)):
        if int(s1[i]) > int(s2[i]): return 1
        elif int(s1[i]) < int(s2[i]): return -1
    return 0

