from enum import Enum

State = Enum('State', 'NONE SEEN APPENDED')

def remember(str_):
    states = {}
    result = []
    for c in str_:
        state = states.get(c, State.NONE)
        if state is State.NONE:
            states[c] = State.SEEN
        elif state is State.SEEN:
            result.append(c)
            states[c] = State.APPENDED
    return result

def simplify(n): 
    output = []
    exp = 0

    while n:
        n, r = divmod(n, 10)
        if r:
            output.append(f"{r}*{10**exp}" if exp else f"{r}")
        exp += 1

    return "+".join(output[::-1])

def simplify(number):
    num = str(number)
    result = []
    for i, d in enumerate(num, start=1):
        if d == "0":
            continue
        elif i == len(num):
            result.append(d)
        else:
            result.append(d + "*" + "1" + "0" * (len(num) - i))
    return "+".join(result)

def is_narcissistic(i):
    sum_of_digits = 0
