def prime(n):
    if n < 2:
        return []
    r = [False,True] * (n//2)+[True]
    r[1],r[2]=False, True
    for i in range(3,int(1 + n**0.5),2):
        if r[i]:
            r[i*i::2*i] = [False] * int((n+2*i-1-i*i)/(2*i))
    r = list(compress(list(range(len(r))),r))
    if r[-1] %2 == 0:
        r.pop() 
    return r
