def max_collatz_length(n):
    if type(n) != int:
        return []
    if n == 0:
        return []
    if n == 1:
        return [1,1]
    try:    
        results=[0 for i in range(n+1)]
        results[0]=1
        results[1]=1

        for num in range(2,n+1):
            col=num
            ctr=0
            shortCut=0

            while(shortCut==0):

                if col%2==0:
                    ctr+=1
                    col=col >> 1
                else:
                    ctr+=2
                    col=(3*col+1)>>1
                if col<n:
                    shortCut=results[col]
            results[num]=results[col]+ctr

        return [results.index(max(results[1:])), max(results[1:])]
    except:
        return []

def max_collatz_length(limit):
    if type(limit) != int or limit < 1:
        return []

    results = {1: 1}

    for n in range(2, limit + 1):
        count = 0
        x = n
        while x not in results:
            x = x * 3 + 1 if x % 2 else x // 2
            count += 1

        count += results[x]
        results[n] = count

    sol = max(results, key=results.get)
    return [ sol, results[sol] ]

class Collatz(object):
    def __init__(self):
        self.memory = {1: 1}

    def calculate(self, n):
        if n in self.memory:
            return self.memory[n]

        result = self.calculate(n // 2) + 1 if n % 2 == 0 else self.calculate(3 * n + 1) + 1
        self.memory[n] = result
        return result


