import heapq
def lemming_battle(n, g, b):
    g = [i*(-1) for i in g]
    b = [i*(-1) for i in b]
    heapq.heapify(g)
    heapq.heapify(b)
    while g and b:
        t1, t2 = [], []
        for _ in range(n):
            if len(g) == 0 or len(b) == 0:
                break
            x = heapq.heappop(g)*(-1)
            y = heapq.heappop(b)*(-1)
            if x > y:
                t1.append(x-y)
            elif x < y:
                t2.append(y-x)
        for i in t1:
            heapq.heappush(g, (-1)*i)
        for i in t2:
            heapq.heappush(b, (-1)*i)
    if len(g)==0 and len(b)==0:
        return "Green and Blue died"
    if len(g) == 0:
        x =' '.join(map(str, map(lambda x: x*(-1), sorted(b))))
        return 'Blue wins: {}'.format(x)
    else:
        x =' '.join(map(str, map(lambda x: x*(-1), sorted(g))))
        return 'Green wins: {}'.format(x)

def fight(fields, green, blue):
    green, blue = sorted(green, reverse=True), sorted(blue, reverse=True)
    for i in range(min(len(green), len(blue), fields)):
        soldier_g, soldier_b = green[i], blue[i]
        if soldier_g > soldier_b:
            green[i], blue[i] = soldier_g - soldier_b, 0
        elif soldier_g < soldier_b:
            green[i], blue[i] = 0, soldier_b - soldier_g
        else:
            green[i], blue[i] = 0, 0
    green, blue = [s for s in green if s > 0], [s for s in blue if s > 0]
    return green, blue



