def isTree(matrix):
    seen = [False] * len(matrix)

    def traverse(from_node, to_node):
        if not seen[to_node]:
            seen[to_node] = True
            for next_node in matrix[to_node]:
                if next_node != from_node:
                    if not traverse(to_node, next_node):
                        return False
            return True

    return traverse(None, 0) and all(seen)

def isTree(matrix):
    visited_nodes = set([0])
    crossed_edges = set()
    agenda = [0]

    while agenda:
        node = agenda.pop()
        for i in matrix[node]:
            if (node, i) in crossed_edges: continue 
            if i in visited_nodes: return False
            agenda.append(i)
            crossed_edges.add( (i, node) )
            visited_nodes.add(i)

    return len(visited_nodes) == len(matrix)

def isTree(m):
    status = [(e, 0) for e in m[0]]
    seen = set([0]) if status else set()
    while status:
        t, f = status.pop()
        seen.add(t)
        for e in m[t]:
            if e != f:
                if e in seen:
                    return False
                seen.add(e)
                status.append((e, t))
    return len(seen) == len(m)

