    result = [c + '0' * (len(d[0]) - i - 1) for i, c in enumerate(d[0]) if c != '0']
    if len(d) == 2:
        result += ['.' + '0' * i + c for i, c in enumerate(d[1]) if c != '0']
    return result

def to_bytes(n):
    if not n:
        return ['00000000']

    res = []
    while n:
        res.append('{:08b}'.format(n % 256))
        n //= 256

    return res[::-1]

