def pattern(n):
    if n < 1: return ""

    s = "1234567890" * (n//10 + 1)
    width = 2 * n - 1

    triangle = [(s[:i+1] + s[:i][::-1]).center(width) for i in range(n)]

    return "\n".join(triangle + triangle[:-1][::-1])

def pattern(n):
    mid = ''
    nums = '1234567890'*n
    for i in range(n):
        mid += nums[i]
    mid += mid[-2::-1]

    d = []
    for i in range(n-1):
        d.append(''.join(mid.rsplit(mid[i:-i-1], 1)).center(2*n-1))
    d.append(mid)
    for j in d[-2::-1]:
        d.append(j)

    return '\n'.join(d)

def pattern(n):
