        result.append(" " * (n - i) + nums + nums[::-1][1:] + " " * (n - i))
    return "\n".join(result + result[::-1][1:])

def pattern(n):
    lines = []
    for i in range(1, n + 1):
        line = ' ' * (n - i)
        line += ''.join(str(j % 10) for j in range(1, i + 1))
        line += line[::-1][1:]
        lines.append(line)
    return '\n'.join(lines + lines[::-1][1:])

from itertools import chain, cycle, islice

def pattern(n):
    w = 2*n - 1
    def f():
        for i in chain(range(1, n+1), range(n-1, 0, -1)):
            xs = ''.join(islice(cycle('1234567890'), i))
            yield (xs + xs[-2::-1]).center(w)
    return '\n'.join(f())

