    for n in range(num+1, 3*num, 1):
        if prime(n):
            res.append(n)
            break
    return res

def prime_bef_aft(num):
    after = num + 1
    while not isprime(after):
        after += 1

    before = num - 1
    while not isprime(before):
        before -= 1

    return[before, after]


