def group_ints(lst, key=0):
    first = []
    second = []
    final = []
    for i in lst:
        if i < key:
            if second:
                final.append(second)
                second = []
            first.append(i)
        else:
            if first:
                final.append(first)
                first = []
            second.append(i)
    if first:
        final.append(first)
    if second:
        final.append(second)
    return final

def group_ints(lst, key=0):
    if not lst: return []
    l, index = [[lst[0]]], 0
    for x in lst[1:]:
        if l[index][-1] < key and x < key:
            l[index].append(x)
        elif l[index][-1] >= key and x >= key:
            l[index].append(x)
        else:
            l.append([x])
            index += 1
    return l

from itertools import groupby

def group_ints(lst, key=0):
    return [list(g) for _, g in groupby(lst, key.__gt__)]

